import time, random, heapq


def _validate(inp):
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [j["id"] for j in jobs]
    idx = {}
    for i, x in enumerate(ids):
        idx[x] = i
    for j in jobs:
        for p in j.get("after") or []:
            if p not in idx:
                return "job %s references unknown job %s" % (j["id"], p)
        for r, q in (j.get("requires") or {}).items():
            if r not in res:
                return "job %s references unknown resource %s" % (j["id"], r)
            if q > res[r]:
                return "job %s requires %s units of %s but capacity is %s" % (j["id"], q, r, res[r])
    n = len(jobs)
    succ = [[] for _ in range(n)]
    indeg = [0] * n
    for i, j in enumerate(jobs):
        for p in j.get("after") or []:
            succ[idx[p]].append(i)
            indeg[i] += 1
    dq = [i for i in range(n) if indeg[i] == 0]
    d2 = indeg[:]
    k = 0
    while k < len(dq):
        u = dq[k]; k += 1
        for v in succ[u]:
            d2[v] -= 1
            if d2[v] == 0:
                dq.append(v)
    if len(dq) < n:
        left = [ids[i] for i in range(n) if d2[i] > 0]
        return "precedence cycle among " + ", ".join(str(x) for x in left[:6])
    return None


def solve(state, params):
    t0 = time.perf_counter()
    BUDGET = 0.9
    inp = state["input"]
    reason = _validate(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    resn = list((inp.get("resources") or {}).keys())
    ridx = {r: i for i, r in enumerate(resn)}
    cap = [inp["resources"][r] for r in resn]
    jobs = inp["jobs"]
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    ids = [j["id"] for j in jobs]
    idx = {x: i for i, x in enumerate(ids)}
    dur = [max(0, int(j.get("duration", 0))) for j in jobs]
    rel = [max(0, int(j.get("release", 0))) for j in jobs]
    preds = [sorted(set(idx[p] for p in (j.get("after") or []))) for j in jobs]
    succ = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succ[p].append(i)
    req = []
    for i, j in enumerate(jobs):
        lst = []
        for r, q in (j.get("requires") or {}).items():
            if q > 0 and dur[i] > 0:
                lst.append((ridx[r], q))
        req.append(lst)
    R = len(cap)

    indeg0 = [len(preds[i]) for i in range(n)]
    d2 = indeg0[:]
    topo = [i for i in range(n) if d2[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for v in succ[u]:
            d2[v] -= 1
            if d2[v] == 0:
                topo.append(v)
    tpos = [0] * n
    for p, i in enumerate(topo):
        tpos[i] = p
    H = max(rel) + sum(dur) + 2

    head = [0] * n
    for i in topo:
        h = rel[i]
        for p in preds[i]:
            if head[p] + dur[p] > h:
                h = head[p] + dur[p]
        head[i] = h
    tail = [0] * n
    for i in reversed(topo):
        t = 0
        for s in succ[i]:
            if tail[s] > t:
                t = tail[s]
        tail[i] = t + dur[i]
    LB = max(head[i] + tail[i] for i in range(n))
    for r in range(R):
        e = 0
        mr = None
        for i in range(n):
            for rr, q in req[i]:
                if rr == r:
                    e += q * dur[i]
                    mr = rel[i] if mr is None else min(mr, rel[i])
        if e > 0 and cap[r] > 0:
            LB = max(LB, mr + -(-e // cap[r]))
    nsucc = [0] * n
    desc = [set() for _ in range(n)]
    for i in reversed(topo):
        s = set()
        for v in succ[i]:
            s.add(v)
            s |= desc[v]
        desc[i] = s
        nsucc[i] = len(s)

    def new_use():
        return [[0] * H for _ in range(R)]

    def earliest(use, i, t):
        d = dur[i]
        rq = req[i]
        if d == 0 or not rq:
            return t
        while True:
            ok = True
            u = t
            end = t + d
            while u < end:
                bad = False
                for r, q in rq:
                    if use[r][u] + q > cap[r]:
                        bad = True
                        break
                if bad:
                    t = u + 1
                    ok = False
                    break
                u += 1
            if ok:
                return t

    def place(use, i, t):
        for r, q in req[i]:
            row = use[r]
            for u in range(t, t + dur[i]):
                row[u] += q

    def decode(keys):
        use = new_use()
        indeg = indeg0[:]
        hp = [(keys[i], i) for i in range(n) if indeg[i] == 0]
        heapq.heapify(hp)
        st = [0] * n
        while hp:
            _, i = heapq.heappop(hp)
            e = rel[i]
            for p in preds[i]:
                f = st[p] + dur[p]
                if f > e:
                    e = f
            t = earliest(use, i, e)
            st[i] = t
            place(use, i, t)
            for v in succ[i]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    heapq.heappush(hp, (keys[v], v))
        return st

    def forward(st):
        order = sorted(range(n), key=lambda i: (st[i], tpos[i]))
        use = new_use()
        ns = [0] * n
        for i in order:
            e = rel[i]
            for p in preds[i]:
                f = ns[p] + dur[p]
                if f > e:
                    e = f
            t = earliest(use, i, e)
            ns[i] = t
            place(use, i, t)
        return ns

    def backward(st):
        M = max(st[i] + dur[i] for i in range(n))
        order = sorted(range(n), key=lambda i: (-(st[i] + dur[i]), -tpos[i]))
        use = new_use()
        ns = [0] * n
        for i in order:
            lf = M
            for s in succ[i]:
                if ns[s] < lf:
                    lf = ns[s]
            d = dur[i]
            rq = req[i]
            s0 = lf - d
            if d == 0 or not rq:
                t = s0
            else:
                t = s0
                found = None
                while t >= rel[i]:
                    bad = False
                    u = t + d - 1
                    while u >= t:
                        for r, q in rq:
                            if use[r][u] + q > cap[r]:
                                bad = True
                                break
                        if bad:
                            break
                        u -= 1
                    if bad:
                        t = u - d
                    else:
                        found = t
                        break
                t = found if found is not None else st[i]
            if t < rel[i]:
                t = st[i]
            ns[i] = t
            place(use, i, t)
        return ns

    def mk(st):
        return max(st[i] + dur[i] for i in range(n))

    def improve(st):
        best_l = st
        bm_l = mk(st)
        for _ in range(4):
            b = backward(best_l)
            f = forward(b)
            m = mk(f)
            if m < bm_l:
                best_l, bm_l = f, m
            else:
                break
        return best_l, bm_l

    def valid(st):
        for i in range(n):
            if not isinstance(st[i], int) or st[i] < rel[i]:
                return False
            for p in preds[i]:
                if st[i] < st[p] + dur[p]:
                    return False
        use = new_use()
        for i in range(n):
            for r, q in req[i]:
                if st[i] + dur[i] > H:
                    return False
                for u in range(st[i], st[i] + dur[i]):
                    use[r][u] += q
                    if use[r][u] > cap[r]:
                        return False
        return True

    rng = random.Random(12345)
    LS = [LB - tail[i] for i in range(n)]
    energy = [dur[i] * sum(q / cap[r] for r, q in req[i]) for i in range(n)]
    rules = [
        LS[:],
        [-tail[i] for i in range(n)],
        [head[i] for i in range(n)],
        [-nsucc[i] for i in range(n)],
        [LS[i] - 0.5 * energy[i] for i in range(n)],
        [-(tail[i] + sum(energy[s] for s in desc[i])) for i in range(n)],
        [float(tpos[i]) for i in range(n)],
    ]
    first = decode(rules[-1])
    best = first
    bm = mk(first)

    def consider(st):
        nonlocal best, bm
        st2, m2 = improve(st)
        if m2 < bm and valid(st2):
            best, bm = st2, m2
        return st2, m2

    for kk in rules:
        if bm <= LB or time.perf_counter() - t0 > BUDGET:
            break
        consider(decode([kk[i] + 1e-6 * tpos[i] for i in range(n)]))

    scale = max(1.0, float(max(tail) + max(rel)))
    it = 0
    while bm > LB and time.perf_counter() - t0 < BUDGET:
        it += 1
        if rng.random() < 0.4:
            base = rules[rng.randrange(len(rules) - 1)]
            noise = rng.choice([0.05, 0.15, 0.3, 0.6]) * scale
            keys = [base[i] + rng.random() * noise for i in range(n)]
        else:
            keys = [best[i] + 0.001 * tpos[i] + rng.random() * 0.0001 for i in range(n)]
            nm = rng.randint(1, 3)
            for _ in range(nm):
                a = rng.randrange(n)
                if rng.random() < 0.5:
                    b = rng.randrange(n)
                    keys[a], keys[b] = keys[b], keys[a]
                else:
                    keys[a] += (rng.random() - 0.5) * 2 * rng.choice([2, 5, 10])
        consider(decode(keys))

    if not valid(best):
        best = first
        if not valid(best):
            best = forward(first)
    state["output"] = {"status": "ok", "start": {ids[i]: int(best[i]) for i in range(n)}}
    state["iters"] = it
    state["lb"] = LB
    state["mk"] = bm
    return state

