    req = []
    for j in jobs:
        rq = j.get("requires") or {}
        req.append([(rnames.index(r), int(u)) for r, u in rq.items() if int(u) > 0])
    for i in range(n):
        if dur[i] == 0:
            req[i] = []
    H = max(rel + [0]) + sum(dur) + 30
    indeg = [len(preds[i]) for i in range(n)]
    topo = []
    q = [i for i in range(n) if indeg[i] == 0]
    while q:
        v = q.pop()
        topo.append(v)
        for w in succ[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                q.append(w)
    head = [0] * n
    for v in topo:
        h = rel[v]
        for p in preds[v]:
            h = max(h, head[p] + dur[p])
        head[v] = h
    tail = [0] * n
    for v in reversed(topo):
        t = 0
        for s in succ[v]:
            t = max(t, dur[s] + tail[s])
        tail[v] = t
    LB = max([head[i] + dur[i] + tail[i] for i in range(n)] + [0])
    for r in range(R):
        js = [i for i in range(n) if any(rr == r for rr, u in req[i])]
        if not js or cap[r] <= 0:
            continue
        js.sort(key=lambda i: head[i])
        for k in range(len(js)):
            sub = js[k:]
            e = sum(dur[i] * dict(req[i])[r] for i in sub)
            mt = min(tail[i] for i in sub)
            LB = max(LB, head[js[k]] + -(-e // cap[r]) + mt)

    def place(usage, j, t, sign):
        d = dur[j]
        for r, u in req[j]:
            row = usage[r]
            for s in range(t, t + d):
                row[s] += sign * u

    def conflict(usage, j, t):
        d = dur[j]
        for r, u in req[j]:
            row = usage[r]
            lim = cap[r] - u
            for s in range(t + d - 1, t - 1, -1):
                if row[s] > lim:
                    return s
        return -1

    def conflict_lo(usage, j, t):
        d = dur[j]
        best = -1
        for r, u in req[j]:
            row = usage[r]
            lim = cap[r] - u
            for s in range(t, t + d):
                if row[s] > lim:
                    if best == -1 or s < best:
                        best = s
                    break
        return best

    def ssgs(order):
        usage = [[0] * H for _ in range(R)]
        start = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = start[p] + dur[p]
                if f > t:
                    t = f
            if req[j]:
                while True:
                    s = conflict(usage, j, t)
                    if s < 0:
                        break
                    t = s + 1
                place(usage, j, t, 1)
            start[j] = t
        return start, usage

    def justify(start, usage):
        M = max([start[i] + dur[i] for i in range(n)] + [0])
        order = sorted(range(n), key=lambda i: (-(start[i] + dur[i]), -start[i]))
        for j in order:
            lf = M
            for s in succ[j]:
                if start[s] < lf:
                    lf = start[s]
            t = lf - dur[j]
            if t <= start[j]:
                continue
            if req[j]:
                place(usage, j, start[j], -1)
                while t > start[j]:
                    s = conflict_lo(usage, j, t)
                    if s < 0:
                        break
                    t = s - dur[j]
                if t < start[j]:
                    t = start[j]
                place(usage, j, t, 1)
            start[j] = t
        order = sorted(range(n), key=lambda i: (start[i], -dur[i]))
        for j in order:
            e = rel[j]
            for p in preds[j]:
                f = start[p] + dur[p]
                if f > e:
                    e = f
            if e >= start[j]:
                continue
            t = e
            if req[j]:
                place(usage, j, start[j], -1)
                while t < start[j]:
                    s = conflict(usage, j, t)
                    if s < 0:
                        break
                    t = s + 1
                if t > start[j]:
                    t = start[j]
                place(usage, j, t, 1)
            start[j] = t
        return start

    def mk(start):
        return max([start[i] + dur[i] for i in range(n)] + [0])

    def evaluate(order, passes=2):
        start, usage = ssgs(order)
        m = mk(start)
        for _ in range(passes):
            start = justify(start, usage)
            m2 = mk(start)
            if m2 >= m:
                m = m2
                break
            m = m2
        return m, start

    def list_from_rule(key):
        indeg = [len(preds[i]) for i in range(n)]
        hq = [(key(i), i) for i in range(n) if indeg[i] == 0]
        heapq.heapify(hq)
        out = []
        while hq:
            _, v = heapq.heappop(hq)
            out.append(v)
            for w in succ[v]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    heapq.heappush(hq, (key(w), w))
        return out

    work = [dur[i] * sum(u / max(cap[r], 1) for r, u in req[i]) for i in range(n)]
    lst = [LB - tail[i] - dur[i] for i in range(n)]
    nsucc = [0] * n
    for v in reversed(topo):
        nsucc[v] = len(succ[v]) + sum(nsucc[w] for w in succ[v])
    rules = [
        lambda i: (lst[i], head[i]),
        lambda i: (-(tail[i] + dur[i]), head[i]),
        lambda i: (head[i], lst[i]),
        lambda i: (-nsucc[i], lst[i]),
        lambda i: (lst[i] - work[i], 0),
        lambda i: (-(tail[i] + dur[i] + work[i]), 0),
        lambda i: (head[i] + lst[i], 0),
    ]
    rng = random.Random(12345)
    best_m = None
    best_s = None
    best_list = None

    def consider(m, s):
        nonlocal best_m, best_s, best_list
        if best_m is None or m < best_m:
            best_m = m
            best_s = list(s)
            best_list = sorted(range(n), key=lambda i: (s[i], -dur[i]))
            return True
        return False

    for rule in rules:
        o = list_from_rule(rule)
        m, s = evaluate(o)
        consider(m, s)
        if best_m <= LB:
            break

    def mutate(lst_in):
        L = list(lst_in)
        k = rng.randint(1, 3)
        for _ in range(k):
            i = rng.randrange(n)
            v = L[i]
            pos = {x: p for p, x in enumerate(L)}
            lo = max([pos[p] for p in preds[v]] + [-1]) + 1
            hi = min([pos[s] for s in succ[v]] + [n]) - 1
            if hi <= lo:
                continue
            del L[i]
            a = lo if i >= lo else lo - 1
            b = hi if i <= hi else hi + 1
            a = max(0, min(a, len(L)))
            b = max(a, min(b, len(L)))
            L.insert(rng.randint(a, b), v)
        return L

    def biased_random():
        base = [lst[i] for i in range(n)]
        noise = max(1, LB // 4)
        return list_from_rule(lambda i: (base[i] + rng.random() * noise * 2, 0))

    cur_list, cur_m = best_list, best_m
    stall = 0
    it = 0
    while n > 0 and best_m > LB and time.perf_counter() - T0 < BUDGET:
        it += 1
        if stall > 150 + 10 * n:
            o = biased_random() if rng.random() < 0.5 else mutate(mutate(best_list))
            m, s = evaluate(o)
            cur_list = sorted(range(n), key=lambda i: (s[i], -dur[i]))
            cur_m = m
            consider(m, s)
            stall = 0
            continue
        o = mutate(cur_list)
        m, s = evaluate(o)
        if m <= cur_m:
            if m < cur_m:
                stall = 0
            else:
                stall += 1
            cur_m = m
            cur_list = sorted(range(n), key=lambda i: (s[i], -dur[i])) if rng.random() < 0.5 else o
        else:
            stall += 1
        consider(m, s)
    if best_s is None:
        best_s = []
    ok = True
    for i in range(n):
        if best_s[i] < rel[i]:
            ok = False
        for p in preds[i]:
            if best_s[i] < best_s[p] + dur[p]:
                ok = False
    usage = [[0] * (H + 20) for _ in range(R)]
    for i in range(n):
        for r, u in req[i]:
            for t in range(best_s[i], best_s[i] + dur[i]):
                usage[r][t] += u
                if usage[r][t] > cap[r]:
                    ok = False
    if not ok:
        best_s, _ = ssgs(list(topo))
    state["output"] = {"status": "ok", "start": {ids[i]: int(best_s[i]) for i in range(n)}}
    state["stats"] = {"makespan": mk(best_s), "lb": LB, "iters": it}
    return state

import time, random, heapq, math


def validate(state, params):
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    state["_infeasible"] = None
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in idset:
                state["_infeasible"] = "job %s references unknown job %s" % (j.get("id"), p)
                return state
        for r, u in (j.get("requires") or {}).items():
            if r not in res:
                state["_infeasible"] = "job %s references unknown resource %s" % (j.get("id"), r)
                return state
            if int(u) > int(res[r]):
                state["_infeasible"] = "job %s requires %s units of %s, capacity %s" % (j.get("id"), u, r, res[r])
                return state
    idx = {}
    for i, s in enumerate(ids):
        if s not in idx:
            idx[s] = i
    n = len(jobs)
    indeg = [0] * n
    succ = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in set(str(x) for x in (j.get("after") or [])):
            succ[idx[p]].append(i)
            indeg[i] += 1
    q = [i for i in range(n) if indeg[i] == 0]
    seen = 0
    while q:
        x = q.pop()
        seen += 1
        for y in succ[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                q.append(y)
    if seen < n:
        cyc = [ids[i] for i in range(n) if indeg[i] > 0]
        state["_infeasible"] = "precedence cycle among " + ", ".join(cyc[:6])
    return state


def emit_infeasible(state, params):
    state["output"] = {"status": "infeasible", "reason": state.get("_infeasible") or "infeasible"}
    return state


def solve(state, params):
    t0 = time.perf_counter()
    budget = 0.95
    inp = state["input"]
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    caps = [int(res[r]) for r in rnames]
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        if s not in idx:
            idx[s] = i
    dur = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0)) for j in jobs]
    preds = [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    req = []
    for j in jobs:
        lst = []
        for r, u in (j.get("requires") or {}).items():
            u = int(u)
            if u > 0:
                lst.append((ridx[r], caps[ridx[r]] - u, u))
        req.append(lst)
    H = sum(dur) + max(rel + [0]) + 2
    zero = [0] * n
    R = len(caps)

    def sgs(pos, P, rl):
        indeg = [len(P[i]) for i in range(n)]
        S = [[] for _ in range(n)]
        for i in range(n):
            for p in P[i]:
                S[p].append(i)
        usage = [[0] * H for _ in range(R)]
        est = list(rl)
        st = [0] * n
        heap = [(pos[i], i) for i in range(n) if indeg[i] == 0]
        heapq.heapify(heap)
        while heap:
            _, j = heapq.heappop(heap)
            d = dur[j]
            t = est[j]
            rq = req[j]
            if d > 0 and rq:
                while True:
                    ok = True
                    for (r, lim, u) in rq:
                        arr = usage[r]
                        for x in range(t + d - 1, t - 1, -1):
                            if arr[x] > lim:
                                t = x + 1
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, lim, u) in rq:
                    arr = usage[r]
                    for x in range(t, t + d):
                        arr[x] += u
            st[j] = t
            f = t + d
            for y in S[j]:
                if est[y] < f:
                    est[y] = f
                indeg[y] -= 1
                if indeg[y] == 0:
                    heapq.heappush(heap, (pos[y], y))
        return st

    def mk(st):
        m = 0
        for i in range(n):
            if st[i] + dur[i] > m:
                m = st[i] + dur[i]
        return m

    def order_pos(keys):
        o = sorted(range(n), key=lambda i: keys[i])
        pos = [0] * n
        for k, i in enumerate(o):
            pos[i] = k
        return pos

    def fbi(st):
        best = st
        bm = mk(st)
        for _ in range(4):
            fin = [best[i] + dur[i] for i in range(n)]
            rpos = order_pos([(-fin[i], -best[i], i) for i in range(n)])
            rs = sgs(rpos, succs, zero)
            M2 = mk(rs)
            bst = [M2 - rs[i] - dur[i] for i in range(n)]
            fpos = order_pos([(bst[i], best[i], i) for i in range(n)])
            s2 = sgs(fpos, preds, rel)
            m2 = mk(s2)
            if m2 < bm:
                best, bm = s2, m2
            else:
                break
        return best, bm

    topo = []
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    while q:
        x = q.pop()
        topo.append(x)
        for y in succs[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                q.append(y)
    es = [0] * n
    for x in topo:
        e = rel[x]
        for p in preds[x]:
            e = max(e, es[p] + dur[p])
        es[x] = e
    tail = [0] * n
    for x in reversed(topo):
        t = 0
        for y in succs[x]:
            t = max(t, tail[y])
        tail[x] = t + dur[x]
    lb = max([es[i] + tail[i] for i in range(n)] + [0])
    for r in range(R):
        items = [(es[i], tail[i] - dur[i], dur[i] * u)
                 for i in range(n) for (rr, lim, u) in req[i] if rr == r and dur[i] > 0]
        if not items:
            continue
        rhos = sorted(set(a for a, _, _ in items))
        for rho in rhos:
            sub = [it for it in items if it[0] >= rho]
            en = sum(it[2] for it in sub)
            lb = max(lb, rho + (en + caps[r] - 1) // caps[r] + min(it[1] for it in sub))
    ub0 = H
    lf = [0] * n
    for x in reversed(topo):
        v = ub0
        for y in succs[x]:
            v = min(v, lf[y] - dur[y])
        lf[x] = v
    nsucc = [0] * n
    desc = [set() for _ in range(n)]
    for x in reversed(topo):
        for y in succs[x]:
            desc[x].add(y)
            desc[x] |= desc[y]
        nsucc[x] = len(desc[x])
    work = [sum(u for (_, _, u) in req[i]) * dur[i] for i in range(n)]
    rules = [
        [(lf[i], es[i], i) for i in range(n)],
        [(lf[i] - dur[i], i) for i in range(n)],
        [(-tail[i], es[i], i) for i in range(n)],
        [(es[i], -tail[i], i) for i in range(n)],
        [(-nsucc[i], lf[i], i) for i in range(n)],
        [(-(dur[i] + sum(dur[y] for y in succs[i])), lf[i], i) for i in range(n)],
        [(es[i] - tail[i], -work[i], i) for i in range(n)],
        [(-work[i], lf[i], i) for i in range(n)],
    ]
    best = None
    bm = None
    for keys in rules:
        s, m = fbi(sgs(order_pos(keys), preds, rel))
        if best is None or m < bm:
            best, bm = s, m
        if bm <= lb:
            break
    rng = random.Random(12345)
    cur = best
    cm = bm
    it = 0
    stall = 0
    base_keys = [lf[i] - dur[i] for i in range(n)]
    while n > 1 and bm > lb and time.perf_counter() - t0 < budget:
        it += 1
        if stall > 60 and rng.random() < 0.5:
            spread = max(1, max(base_keys) - min(base_keys))
            keys = [(base_keys[i] + rng.random() * spread * rng.random(), i) for i in range(n)]
            cand, m = fbi(sgs(order_pos(keys), preds, rel))
            stall = 0
            cur, cm = cand, m
        else:
            order = sorted(range(n), key=lambda i: (cur[i], cur[i] + dur[i], i))
            k = rng.randint(1, 3)
            for _ in range(k):
                a = rng.randrange(n)
                b = rng.randrange(n)
                if rng.random() < 0.5:
                    order[a], order[b] = order[b], order[a]
                else:
                    x = order.pop(a)
                    order.insert(b, x)
            pos = [0] * n
            for kk, i in enumerate(order):
                pos[i] = kk
            cand, m = fbi(sgs(pos, preds, rel))
            if m <= cm:
                if m < cm:
                    stall = 0
                else:
                    stall += 1
                cur, cm = cand, m
            else:
                stall += 1
        if cm < bm:
            best, bm = cur, cm
    state["output"] = {"status": "ok", "start": {ids[i]: int(best[i]) for i in range(n)}}
    state["_stats"] = {"lb": lb, "mk": bm, "iters": it}
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def _sgs(n, dur, rel, preds, succs, reqs, caps, H, key):
    usage = [[0] * H for _ in caps]
    npred = [len(preds[j]) for j in range(n)]
    ready = [(key[j], j) for j in range(n) if npred[j] == 0]
    heapq.heapify(ready)
    start = [0] * n
    fin = [0] * n
    while ready:
        _, j = heapq.heappop(ready)
        t = rel[j]
        for p in preds[j]:
            if fin[p] > t:
                t = fin[p]
        d = dur[j]
        rq = reqs[j]
        if d > 0 and rq:
            while True:
                bad = -1
                for tau in range(t, t + d):
                    for (r, u) in rq:
                        if usage[r][tau] + u > caps[r]:
                            bad = tau
                            break
                    if bad >= 0:
                        break
                if bad < 0:
                    break
                t = bad + 1
            for tau in range(t, t + d):
                for (r, u) in rq:
                    usage[r][tau] += u
        start[j] = t
        fin[j] = t + d
        for s in succs[j]:
            npred[s] -= 1
            if npred[s] == 0:
                heapq.heappush(ready, (key[s], s))
    return start


def _verify(n, dur, rel, preds, reqs, caps, start):
    for j in range(n):
        if start[j] < rel[j]:
            return False
        for p in preds[j]:
            if start[j] < start[p] + dur[p]:
                return False
    events = {}
    for j in range(n):
        if dur[j] > 0:
            for t in range(start[j], start[j] + dur[j]):
                row = events.setdefault(t, [0] * len(caps))
                for (r, u) in reqs[j]:
                    row[r] += u
    for t, row in events.items():
        for r in range(len(caps)):
            if row[r] > caps[r]:
                return False
    return True


def solve(state, params):
    t0 = time.perf_counter()
    budget = 0.9
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    rnames = list(resources.keys())
    ridx = {name: i for i, name in enumerate(rnames)}
    caps = [int(resources[name]) for name in rnames]

    ids = []
    idx = {}
    for jb in jobs:
        jid = str(jb.get("id"))
        if jid in idx:
            return _infeasible(state, "duplicate job id " + jid)
        idx[jid] = len(ids)
        ids.append(jid)
    n = len(ids)

    dur = [0] * n
    rel = [0] * n
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    reqs = [[] for _ in range(n)]
    for j, jb in enumerate(jobs):
        dur[j] = max(0, int(jb.get("duration", 0) or 0))
        rel[j] = max(0, int(jb.get("release", 0) or 0))
        pset = set()
        for p in (jb.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job " + ids[j] + " references unknown job " + p)
            pset.add(idx[p])
        if j in pset:
            return _infeasible(state, "precedence cycle: " + ids[j] + " depends on itself")
        preds[j] = sorted(pset)
        for p in preds[j]:
            succs[p].append(j)
        rq = []
        for rname, units in (jb.get("requires") or {}).items():
            if rname not in ridx:
                return _infeasible(state, "job " + ids[j] + " requires unknown resource " + str(rname))
            u = int(units)
            r = ridx[rname]
            if u > caps[r]:
                return _infeasible(state, "job " + ids[j] + " requires " + str(u) + " of " + rname + " > capacity " + str(caps[r]))
            if u > 0:
                rq.append((r, u))
        reqs[j] = rq

    # cycle detection / topological order
    indeg = [len(preds[j]) for j in range(n)]
    q = [j for j in range(n) if indeg[j] == 0]
    topo = []
    while q:
        j = q.pop()
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        cyc = [ids[j] for j in range(n) if indeg[j] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc[:6]))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    H = max(rel) + sum(dur) + 2

    # lower bounds and static priorities
    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[j] = t
    cp = max(es[j] + dur[j] for j in range(n))
    lb = cp
    for r in range(len(caps)):
        energy = 0
        mr = None
        for j in range(n):
            for (rr, u) in reqs[j]:
                if rr == r and dur[j] > 0:
                    energy += u * dur[j]
                    mr = rel[j] if mr is None else min(mr, rel[j])
        if energy > 0 and caps[r] > 0:
            lb = max(lb, mr + (energy + caps[r] - 1) // caps[r])
    lft = [cp] * n
    for j in reversed(topo):
        v = cp
        for s in succs[j]:
            if lft[s] - dur[s] < v:
                v = lft[s] - dur[s]
        lft[j] = v
    lst = [lft[j] - dur[j] for j in range(n)]
    nsucc_tot = [0] * n
    for j in reversed(topo):
        seen = set()
        for s in succs[j]:
            seen.add(s)
        nsucc_tot[j] = len(succs[j]) + sum(nsucc_tot[s] for s in succs[j])

    rng = random.Random(12345)
    zeros = [0] * n

    def mk(st):
        return max(st[j] + dur[j] for j in range(n))

    def forward(key):
        return _sgs(n, dur, rel, preds, succs, reqs, caps, H, key)

    def fbi(st):
        best_st = st
        best_m = mk(st)
        for _ in range(4):
            fin = [best_st[j] + dur[j] for j in range(n)]
            bkey = [-fin[j] * 1000.0 - best_st[j] for j in range(n)]
            rs = _sgs(n, dur, zeros, succs, preds, reqs, caps, H, bkey)
            fkey = [-(rs[j] + dur[j]) * 1000.0 + rng.random() * 0.1 for j in range(n)]
            ns = forward(fkey)
            m = mk(ns)
            if m < best_m:
                best_st, best_m = ns, m
            else:
                if m == best_m:
                    best_st = ns
                break
        return best_st, best_m

    best = None
    best_m = None

    def consider(st):
        nonlocal best, best_m
        st2, m2 = fbi(st)
        if best is None or m2 < best_m:
            best, best_m = st2, m2
        return m2

    base_keys = [
        [lst[j] * 1000.0 + j for j in range(n)],
        [lft[j] * 1000.0 + j for j in range(n)],
        [es[j] * 1000.0 + lst[j] for j in range(n)],
        [-nsucc_tot[j] * 1000.0 + lst[j] for j in range(n)],
        [lst[j] * 1000.0 - dur[j] for j in range(n)],
        [max(rel[j], lst[j]) * 1000.0 + j for j in range(n)],
    ]
    for k in base_keys:
        consider(forward(k))
        if best_m <= lb or time.perf_counter() - t0 > budget:
            break

    it = 0
    while best_m > lb and time.perf_counter() - t0 < budget:
        it += 1
        if it % 3 == 0:
            scale = rng.choice([0.5, 1.0, 2.0, 4.0])
            key = [lst[j] + rng.random() * scale * (1 + abs(lst[j]) * 0.1) for j in range(n)]
        else:
            key = [best[j] * 10.0 + rng.random() for j in range(n)]
            moves = rng.randint(1, 3)
            span = max(1, best_m)
            for _ in range(moves):
                if rng.random() < 0.5:
                    a = rng.randrange(n)
                    b = rng.randrange(n)
                    key[a], key[b] = key[b], key[a]
                else:
                    a = rng.randrange(n)
                    key[a] += rng.uniform(-span / 3.0, span / 3.0) * 10.0
        consider(forward(key))

    if best is None or not _verify(n, dur, rel, preds, reqs, caps, best):
        # guaranteed-valid sequential fallback
        st = [0] * n
        t = 0
        for j in topo:
            s = max(t, rel[j])
            for p in preds[j]:
                s = max(s, st[p] + dur[p])
            st[j] = s
            t = s + dur[j]
        best = st

    state["output"] = {"status": "ok", "start": {ids[j]: int(best[j]) for j in range(n)}}
    return state

import time, random, heapq

def validate(state, params):
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, x in enumerate(ids):
        if x not in idx:
            idx[x] = i
    reason = None
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in idx:
                reason = "job %s references unknown job %s" % (j.get("id"), p); break
        if reason: break
        for r, q in (j.get("requires") or {}).items():
            if r not in res:
                reason = "job %s requires unknown resource %s" % (j.get("id"), r); break
            if int(q) > int(res[r]):
                reason = "job %s requires %s %s > capacity %s" % (j.get("id"), q, r, res[r]); break
        if reason: break
    n = len(jobs)
    topo = []
    if reason is None:
        indeg = [0] * n
        succ = [[] for _ in range(n)]
        for i, j in enumerate(jobs):
            for p in set(str(p) for p in (j.get("after") or [])):
                succ[idx[p]].append(i); indeg[i] += 1
        q = [i for i in range(n) if indeg[i] == 0]
        while q:
            u = q.pop()
            topo.append(u)
            for v in succ[u]:
                indeg[v] -= 1
                if indeg[v] == 0: q.append(v)
        if len(topo) < n:
            cyc = [ids[i] for i in range(n) if indeg[i] > 0]
            reason = "precedence cycle among " + ", ".join(cyc[:6])
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        state["feasible"] = False
        return state
    rnames = list(res.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    prob = {"n": n, "ids": ids, "cap": [int(res[r]) for r in rnames],
            "dur": [max(0, int(j.get("duration", 0))) for j in jobs],
            "rel": [max(0, int(j.get("release", 0))) for j in jobs],
            "preds": [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs],
            "req": [[[ridx[r], int(q)] for r, q in (j.get("requires") or {}).items() if int(q) > 0] for j in jobs],
            "topo": topo}
    state["prob"] = prob
    state["feasible"] = True
    return state


def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 1.0
    P = state["prob"]
    n = P["n"]; cap = P["cap"]; dur = P["dur"]; rel = P["rel"]; preds = P["preds"]
    req = [[tuple(x) for x in r] for r in P["req"]]
    topo = P["topo"]; R = len(cap)
    for i in range(n):
        if dur[i] == 0: req[i] = []
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    tpos = [0] * n
    for k, i in enumerate(topo): tpos[i] = k
    H = (max(rel) if n else 0) + sum(dur) + 2
    head = [0] * n
    for i in topo:
        h = rel[i]
        for p in preds[i]:
            h = max(h, head[p] + dur[p])
        head[i] = h
    tail = [0] * n
    for i in reversed(topo):
        t = 0
        for s in succs[i]:
            t = max(t, tail[s])
        tail[i] = t + dur[i]
    LB = max(head[i] + tail[i] for i in range(n)) if n else 0
    for r in range(R):
        en = 0; mr = None
        for i in range(n):
            for (rr, q) in req[i]:
                if rr == r:
                    en += q * dur[i]
                    mr = head[i] if mr is None else min(mr, head[i])
        if en:
            LB = max(LB, mr + -(-en // cap[r]))
    for r in range(R):
        big = [i for i in range(n) if any(rr == r and 2 * q > cap[r] for rr, q in req[i])]
        if big:
            LB = max(LB, min(head[i] for i in big) + sum(dur[i] for i in big))

    def fits(use, i, t):
        d = dur[i]
        for (r, q) in req[i]:
            u = use[r]; c = cap[r] - q
            for tt in range(t + d - 1, t - 1, -1):
                if u[tt] > c:
                    return tt
        return -1

    def place(use, i, t):
        d = dur[i]
        for (r, q) in req[i]:
            u = use[r]
            for tt in range(t, t + d):
                u[tt] += q

    def newuse(h):
        return [[0] * h for _ in range(R)]

    def sgs(order):
        h = H
        use = newuse(h)
        st = [0] * n
        for i in order:
            t = rel[i]
            for p in preds[i]:
                f = st[p] + dur[p]
                if f > t: t = f
            if req[i]:
                while True:
                    if t + dur[i] > h:
                        ext = t + dur[i] - h + 64
                        for u in use: u.extend([0] * ext)
                        h += ext
                    c = fits(use, i, t)
                    if c < 0: break
                    t = c + 1
                place(use, i, t)
            st[i] = t
        return st

    def mk(st):
        return max(st[i] + dur[i] for i in range(n)) if n else 0

    def fbi(st):
        best = mk(st)
        while True:
            T = best
            use = newuse(T + 1)
            order = sorted(range(n), key=lambda i: (-(st[i] + dur[i]), -tpos[i]))
            nb = [0] * n
            for i in order:
                ub = T
                for s in succs[i]:
                    if nb[s] < ub: ub = nb[s]
                t = ub - dur[i]
                if req[i]:
                    while True:
                        c = fits(use, i, t)
                        if c < 0: break
                        t = c - dur[i]
                    place(use, i, t)
                nb[i] = t
            use = newuse(T + 1)
            order = sorted(range(n), key=lambda i: (nb[i], tpos[i]))
            nf = [0] * n
            for i in order:
                t = rel[i]
                for p in preds[i]:
                    f = nf[p] + dur[p]
                    if f > t: t = f
                if req[i]:
                    while True:
                        c = fits(use, i, t)
                        if c < 0: break
                        t = c + 1
                    place(use, i, t)
                nf[i] = t
            m = mk(nf)
            if m < best:
                best = m; st = nf
            else:
                if m == best: st = nf
                return st, best

    def order_of(st):
        return sorted(range(n), key=lambda i: (st[i], tpos[i]))

    rng = random.Random(12345)
    best_st = None; best_m = None

    def consider(st):
        nonlocal best_st, best_m
        st, m = fbi(st)
        if best_m is None or m < best_m:
            best_m = m; best_st = st[:]
        return st, m

    work = [sum(q * dur[i] for (r, q) in req[i]) for i in range(n)]
    rules = [
        lambda i: (-tail[i], head[i]),
        lambda i: (head[i], -tail[i]),
        lambda i: (head[i] - (LB - tail[i]), -tail[i]),
        lambda i: (-(tail[i] + work[i] * 0.05), head[i]),
        lambda i: (-len(succs[i]), -tail[i]),
        lambda i: (-work[i], -tail[i]),
    ]

    def list_by_prio(key, noise=0.0):
        indeg = [len(preds[i]) for i in range(n)]
        heap = []
        keys = {}
        for i in range(n):
            k = key(i)
            if noise:
                k = (k[0] + rng.uniform(-noise, noise) * (abs(k[0]) + 1),) + tuple(k[1:])
            keys[i] = k
            if indeg[i] == 0: heapq.heappush(heap, (k, i))
        out = []
        while heap:
            _, u = heapq.heappop(heap)
            out.append(u)
            for s in succs[u]:
                indeg[s] -= 1
                if indeg[s] == 0: heapq.heappush(heap, (keys[s], s))
        return out

    def elapsed():
        return time.perf_counter() - T0

    for key in rules:
        consider(sgs(list_by_prio(key)))
        if best_m <= LB: break
    while best_m > LB and elapsed() < BUDGET * 0.3:
        key = rules[rng.randrange(len(rules))]
        consider(sgs(list_by_prio(key, noise=rng.choice([0.1, 0.3, 0.6]))))
    cur = order_of(best_st); cur_m = best_m
    stall = 0
    while best_m > LB and elapsed() < BUDGET:
        lst = cur[:]
        for _ in range(rng.choice([1, 1, 1, 2, 3])):
            pos = {v: k for k, v in enumerate(lst)}
            i = rng.randrange(n)
            a = pos[i]
            lo = max([pos[p] for p in preds[i]], default=-1) + 1
            hi = min([pos[s] for s in succs[i]], default=n) - 1
            if hi <= lo: continue
            b = rng.randint(lo, hi)
            if b == a: continue
            lst.pop(a)
            lst.insert(b, i)
        st, m = consider(sgs(lst))
        if m <= cur_m:
            if m < cur_m: stall = 0
            else: stall += 1
            cur = order_of(st); cur_m = m
        else:
            stall += 1
        if stall > 300:
            stall = 0
            if rng.random() < 0.5:
                st, m = consider(sgs(list_by_prio(rules[rng.randrange(len(rules))], noise=0.5)))
                cur = order_of(st); cur_m = m
            else:
                cur = order_of(best_st); cur_m = best_m
    state["sched"] = best_st
    state["makespan"] = best_m
    state["lb"] = LB
    return state


def finalize(state, params):
    P = state["prob"]
    n = P["n"]; cap = P["cap"]; dur = P["dur"]; rel = P["rel"]; preds = P["preds"]; req = P["req"]
    st = state.get("sched")

    def ok(st):
        if st is None or len(st) != n: return False
        ev = {}
        for i in range(n):
            if st[i] < rel[i]: return False
            for p in preds[i]:
                if st[i] < st[p] + dur[p]: return False
            if dur[i] > 0:
                for (r, q) in req[i]:
                    for t in range(st[i], st[i] + dur[i]):
                        ev[(r, t)] = ev.get((r, t), 0) + q
                        if ev[(r, t)] > cap[r]: return False
        return True

    if not ok(st):
        st = [0] * n; t = 0
        for i in P["topo"]:
            s = max(t, rel[i])
            for p in preds[i]: s = max(s, st[p] + dur[p])
            st[i] = s; t = s + dur[i]
    out = {}
    for i in range(n):
        if P["ids"][i] not in out:
            out[P["ids"][i]] = int(st[i])
    state["output"] = {"status": "ok", "start": out}
    return state

import time, random, math, heapq


def _validate(inp):
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in idx:
                return "job %s references unknown job %s" % (j.get("id"), p)
        for r, u in (j.get("requires") or {}).items():
            if r not in res:
                return "job %s references unknown resource %s" % (j.get("id"), r)
            if int(u) > int(res[r]):
                return "job %s requires %s units of %s but capacity is %s" % (j.get("id"), u, r, res[r])
    n = len(jobs)
    indeg = [0] * n
    succ = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        ps = set(idx[str(p)] for p in (j.get("after") or []))
        for p in ps:
            succ[p].append(i)
            indeg[i] += 1
    q = [i for i in range(n) if indeg[i] == 0]
    seen = 0
    while q:
        x = q.pop()
        seen += 1
        for s in succ[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if seen < n:
        cyc = [ids[i] for i in range(n) if indeg[i] > 0]
        return "precedence cycle among " + ", ".join(cyc[:6])
    return None


def solve(state, params):
    t_begin = time.perf_counter()
    budget = 0.95
    inp = state["input"]
    reason = _validate(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    resd = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    ids = [str(j.get("id")) for j in jobs]
    idx = {s: i for i, s in enumerate(ids)}
    rnames = list(resd.keys())
    rix = {r: k for k, r in enumerate(rnames)}
    cap = [int(resd[r]) for r in rnames]
    R = len(rnames)
    dur = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    req = []
    for j in jobs:
        lst = []
        for r, u in (j.get("requires") or {}).items():
            u = int(u)
            if u > 0:
                lst.append((rix[r], u))
        req.append(lst)
    active = [dur[i] > 0 and len(req[i]) > 0 for i in range(n)]
    preds = [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop(0)
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    pos = [0] * n
    for k, x in enumerate(topo):
        pos[x] = k
    head = [0] * n
    for x in topo:
        h = rel[x]
        for p in preds[x]:
            h = max(h, head[p] + dur[p])
        head[x] = h
    tail = [0] * n
    for x in reversed(topo):
        t = 0
        for s in succs[x]:
            t = max(t, tail[s])
        tail[x] = dur[x] + t
    LB = max(head[i] + tail[i] for i in range(n))
    for r in range(R):
        e = 0
        mr = None
        mt = None
        for i in range(n):
            for (rr, u) in req[i]:
                if rr == r and dur[i] > 0:
                    e += u * dur[i]
                    mr = head[i] if mr is None else min(mr, head[i])
                    tt = tail[i] - dur[i]
                    mt = tt if mt is None else min(mt, tt)
        if e > 0:
            LB = max(LB, mr + (e + cap[r] - 1) // cap[r] + mt)
    desc = [set() for _ in range(n)]
    for x in reversed(topo):
        for s in succs[x]:
            desc[x].add(s)
            desc[x] |= desc[s]
    ndesc = [len(desc[i]) for i in range(n)]
    H = max(rel) + sum(dur) + max(dur) + 3
    L = H + max(dur) + 3

    def sgs(order):
        usage = [[0] * L for _ in range(R)]
        start = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = start[p] + dur[p]
                if f > t:
                    t = f
            if active[j]:
                d = dur[j]
                rq = req[j]
                while True:
                    ok = True
                    for (r, u) in rq:
                        lim = cap[r] - u
                        ur = usage[r]
                        for k in range(t + d - 1, t - 1, -1):
                            if ur[k] > lim:
                                t = k + 1
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    ur = usage[r]
                    for k in range(t, t + d):
                        ur[k] += u
            start[j] = t
        return start, usage

    def fits(usage, rq, t, d):
        for (r, u) in rq:
            lim = cap[r] - u
            ur = usage[r]
            for k in range(t, t + d):
                if ur[k] > lim:
                    return k
        return -1

    def place(usage, rq, t, d, sign):
        for (r, u) in rq:
            ur = usage[r]
            v = u * sign
            for k in range(t, t + d):
                ur[k] += v

    def fbi(start, usage):
        ms = max(start[i] + dur[i] for i in range(n))
        for _ in range(4):
            order = sorted(range(n), key=lambda i: (-(start[i] + dur[i]), -pos[i]))
            for j in order:
                d = dur[j]
                latest = ms - d
                for s in succs[j]:
                    v = start[s] - d
                    if v < latest:
                        latest = v
                if latest <= start[j]:
                    continue
                if not active[j]:
                    start[j] = latest
                    continue
                rq = req[j]
                place(usage, rq, start[j], d, -1)
                t = latest
                while t > start[j]:
                    c = fits(usage, rq, t, d)
                    if c < 0:
                        break
                    t = c - d
                if t < start[j]:
                    t = start[j]
                start[j] = t
                place(usage, rq, t, d, 1)
            order = sorted(range(n), key=lambda i: (start[i], pos[i]))
            for j in order:
                d = dur[j]
                t0 = rel[j]
                for p in preds[j]:
                    f = start[p] + dur[p]
                    if f > t0:
                        t0 = f
                if t0 >= start[j]:
                    continue
                if not active[j]:
                    start[j] = t0
                    continue
                rq = req[j]
                place(usage, rq, start[j], d, -1)
                t = t0
                while t < start[j]:
                    c = fits(usage, rq, t, d)
                    if c < 0:
                        break
                    t = c + 1
                if t > start[j]:
                    t = start[j]
                start[j] = t
                place(usage, rq, t, d, 1)
            nms = max(start[i] + dur[i] for i in range(n))
            if nms >= ms:
                ms = nms
                break
            ms = nms
        return start, ms

    def evaluate(order):
        start, usage = sgs(order)
        start, ms = fbi(start, usage)
        norder = sorted(range(n), key=lambda i: (start[i], pos[i]))
        return ms, norder, start

    def prio_order(key):
        indeg2 = [len(preds[i]) for i in range(n)]
        heap = [(key[i], pos[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(heap)
        out = []
        while heap:
            _, _, x = heapq.heappop(heap)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(heap, (key[s], pos[s], s))
        return out

    rng = random.Random(12345)
    best = [None, None]

    def consider(ms, start):
        if best[0] is None or ms < best[0]:
            best[0] = ms
            best[1] = list(start)

    def timeup():
        return time.perf_counter() - t_begin > budget

    work = [sum(u for (_, u) in req[i]) * dur[i] for i in range(n)]
    keys = [
        [-tail[i] for i in range(n)],
        [head[i] for i in range(n)],
        [(head[i], -tail[i]) for i in range(n)],
        [-ndesc[i] for i in range(n)],
        [-(tail[i] + head[i]) for i in range(n)],
        [-(tail[i] * 10 + work[i]) for i in range(n)],
        [(-tail[i] + head[i]) for i in range(n)],
        [-work[i] for i in range(n)],
        list(pos),
    ]
    pop = []
    for k in keys:
        o = prio_order(k)
        ms, no, st = evaluate(o)
        consider(ms, st)
        pop.append((ms, no))
        if best[0] <= LB or timeup():
            break
    PS = 40
    while len(pop) < PS and best[0] > LB and not timeup():
        a = rng.random() * 0.5
        k = [-(tail[i] + rng.random() * a * (LB + 1)) + head[i] * rng.random() * 0.5 for i in range(n)]
        o = prio_order(k)
        ms, no, st = evaluate(o)
        consider(ms, st)
        pop.append((ms, no))

    def crossover(fa, mo):
        a = rng.randrange(n + 1)
        b = rng.randrange(a, n + 1)
        child = fa[:a]
        used = set(child)
        rest_m = [x for x in mo if x not in used]
        take = rest_m[:b - a]
        child += take
        used.update(take)
        child += [x for x in fa if x not in used]
        return child

    def mutate(o):
        o = list(o)
        for _ in range(rng.randint(1, 3)):
            i = rng.randrange(n)
            x = o.pop(i)
            lo = 0
            hi = len(o)
            pset = preds[x]
            sset = succs[x]
            for k, y in enumerate(o):
                if y in pset:
                    lo = max(lo, k + 1)
            for k in range(len(o) - 1, -1, -1):
                if o[k] in sset:
                    hi = min(hi, k)
            if hi < lo:
                hi = lo
            o.insert(rng.randint(lo, hi), x)
        return o

    while best[0] > LB and not timeup() and n > 1:
        pop.sort(key=lambda t: t[0])

        def pick():
            a = rng.randrange(len(pop))
            b = rng.randrange(len(pop))
            return pop[min(a, b)][1]
        fa = pick()
        mo = pick()
        child = crossover(fa, mo)
        if rng.random() < 0.4:
            child = mutate(child)
        ms, no, st = evaluate(child)
        consider(ms, st)
        if ms <= pop[-1][0]:
            if not any(p[1] == no for p in pop):
                pop[-1] = (ms, no)

    start = best[1]
    state["output"] = {"status": "ok", "start": {ids[i]: int(start[i]) for i in range(n)}}
    state["lb"] = LB
    return state

import time, random, heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 0.95
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in jidx:
                return _infeasible(state, "job %s references unknown job %s" % (j.get("id"), p))
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (j.get("id"), r))
            if int(u) > cap[ridx[r]]:
                return _infeasible(state, "job %s requires %s units of %s > capacity %s" % (j.get("id"), u, r, cap[ridx[r]]))
    dur = [max(0, int(j.get("duration", 0))) for j in jobs]
    rel = [max(0, int(j.get("release", 0))) for j in jobs]
    preds = []
    for j in jobs:
        ps = []
        for p in (j.get("after") or []):
            q = jidx[str(p)]
            if q not in ps:
                ps.append(q)
        preds.append(ps)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    req = []
    for j in jobs:
        rq = []
        for r, u in (j.get("requires") or {}).items():
            if int(u) > 0:
                rq.append((ridx[r], int(u)))
        req.append(rq)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        rem = set(range(n)) - set(topo)
        x = min(rem)
        seen = []
        pos = {}
        while x not in pos:
            pos[x] = len(seen)
            seen.append(x)
            nxt = [p for p in preds[x] if p in rem]
            x = nxt[0]
        cyc = seen[pos[x]:]
        return _infeasible(state, "precedence cycle " + " <- ".join(ids[c] for c in cyc))
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rank = [0] * n
    for k, x in enumerate(topo):
        rank[x] = k
    es = [0] * n
    for x in topo:
        t = rel[x]
        for p in preds[x]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[x] = t
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dur[x] + m
    LB = max(es[i] + tail[i] for i in range(n))
    R = len(cap)
    for r in range(R):
        tot = 0
        mr = None
        for i in range(n):
            for (rr, u) in req[i]:
                if rr == r and dur[i] > 0:
                    tot += u * dur[i]
                    mr = es[i] if mr is None else min(mr, es[i])
        if tot > 0 and cap[r] > 0:
            b = mr + (tot + cap[r] - 1) // cap[r]
            if b > LB:
                LB = b
    H = max(rel) + sum(dur) + 16

    def ssgs(order):
        use = [[0] * H for _ in range(R)]
        st = [0] * n
        ms = 0
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = st[p] + dur[p]
                if f > t:
                    t = f
            d = dur[j]
            rq = req[j]
            if d > 0 and rq:
                while True:
                    ok = True
                    for (r, u) in rq:
                        lim = cap[r] - u
                        ur = use[r]
                        for k in range(t, t + d):
                            if ur[k] > lim:
                                t = k + 1
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    ur = use[r]
                    for k in range(t, t + d):
                        ur[k] += u
            st[j] = t
            if t + d > ms:
                ms = t + d
        return st, ms

    def backward(st, M):
        order = sorted(range(n), key=lambda i: (-(st[i] + dur[i]), -rank[i]))
        use = [[0] * H for _ in range(R)]
        st2 = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if st2[s] < lf:
                    lf = st2[s]
            d = dur[j]
            rq = req[j]
            t = lf - d
            if t < rel[j]:
                return None
            if d > 0 and rq:
                while True:
                    ok = True
                    for (r, u) in rq:
                        lim = cap[r] - u
                        ur = use[r]
                        for k in range(t + d - 1, t - 1, -1):
                            if ur[k] > lim:
                                t = k - d
                                ok = False
                                break
                        if not ok:
                            break
                    if t < rel[j]:
                        return None
                    if ok:
                        break
                for (r, u) in rq:
                    ur = use[r]
                    for k in range(t, t + d):
                        ur[k] += u
            st2[j] = t
        return st2

    def fbi(st, ms):
        for _ in range(4):
            b = backward(st, ms)
            if b is None:
                break
            order = sorted(range(n), key=lambda i: (b[i], rank[i]))
            st2, ms2 = ssgs(order)
            if ms2 < ms:
                st, ms = st2, ms2
            else:
                if ms2 == ms:
                    st = st2
                break
        order = sorted(range(n), key=lambda i: (st[i], rank[i]))
        return st, ms, order

    def gen_list(key):
        deg = [len(preds[i]) for i in range(n)]
        h = [(key[i], rank[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(h, (key[s], rank[s], s))
        return out

    nsucc = [0] * n
    for x in topo:
        reach = set()
        stack = list(succs[x])
        while stack:
            y = stack.pop()
            if y not in reach:
                reach.add(y)
                stack.extend(succs[y])
        nsucc[x] = len(reach)
    work = [dur[i] * sum(u / float(cap[r]) for (r, u) in req[i]) for i in range(n)]
    rules = [
        [-tail[i] for i in range(n)],
        [es[i] - tail[i] for i in range(n)],
        [es[i] for i in range(n)],
        [-nsucc[i] for i in range(n)],
        [es[i] - tail[i] - work[i] for i in range(n)],
        [rel[i] - tail[i] for i in range(n)],
        [-tail[i] - work[i] for i in range(n)],
    ]
    rng = random.Random(12345)
    best = None
    bms = None
    border = None

    def consider(order):
        nonlocal best, bms, border
        st, ms = ssgs(order)
        st, ms, order2 = fbi(st, ms)
        if bms is None or ms < bms:
            best, bms, border = st, ms, order2
        return ms, order2

    consider(list(topo))
    for key in rules:
        consider(gen_list(key))
        if bms <= LB:
            break
    spread = max(1, LB)
    it = 0
    while bms > LB and time.perf_counter() - T0 < BUDGET * 0.4:
        key = rules[it % len(rules)]
        a = rng.choice((0.05, 0.15, 0.3, 0.6))
        k2 = [key[i] + rng.random() * a * spread for i in range(n)]
        consider(gen_list(k2))
        it += 1
    cur = list(border)
    cms = bms
    stall = 0
    while bms > LB and time.perf_counter() - T0 < BUDGET:
        order = list(cur)
        pos = {x: k for k, x in enumerate(order)}
        moves = 1 + (rng.random() < 0.3) + (rng.random() < 0.1)
        for _ in range(moves):
            k = rng.randrange(n)
            x = order[k]
            lo = 0
            for p in preds[x]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = n - 1
            for s in succs[x]:
                if pos[s] - 1 < hi:
                    hi = pos[s] - 1
            if hi <= lo:
                continue
            nk = rng.randint(lo, hi)
            order.pop(k)
            order.insert(nk, x)
            pos = {y: kk for kk, y in enumerate(order)}
        ms, o2 = consider(order)
        if ms <= cms:
            if ms < cms:
                stall = 0
            cur, cms = o2, ms
        else:
            stall += 1
        if stall > 300:
            key = rules[rng.randrange(len(rules))]
            k2 = [key[i] + rng.random() * 0.5 * spread for i in range(n)]
            ms, o2 = consider(gen_list(k2))
            cur, cms = o2, ms
            stall = 0
    st = best

    def verify(st):
        if st is None:
            return False
        mx = max(st[i] + dur[i] for i in range(n))
        use = [[0] * (mx + 1) for _ in range(R)]
        for i in range(n):
            if st[i] < rel[i]:
                return False
            for p in preds[i]:
                if st[i] < st[p] + dur[p]:
                    return False
            for (r, u) in req[i]:
                for k in range(st[i], st[i] + dur[i]):
                    use[r][k] += u
                    if use[r][k] > cap[r]:
                        return False
        return True

    if not verify(st):
        st, _ = ssgs(list(topo))
    state["output"] = {"status": "ok", "start": {ids[i]: int(st[i]) for i in range(n)}}
    return state

import time
import random
import math


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t0 = time.perf_counter()
    budget = 1.0
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    caps = [int(resources[r]) for r in rnames]
    R = len(rnames)

    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, jid in enumerate(ids):
        if jid not in jidx:
            jidx[jid] = i
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    dur = []
    rel = []
    preds = []
    req = []
    for i, j in enumerate(jobs):
        dur.append(max(0, int(j.get("duration", 0) or 0)))
        rel.append(max(0, int(j.get("release", 0) or 0)))
        pl = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], p))
            pi = jidx[p]
            if pi not in pl:
                pl.append(pi)
        preds.append(pl)
        rl = []
        rq = j.get("requires") or {}
        for rn, u in rq.items():
            if rn not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            if u > caps[ridx[rn]]:
                return _infeasible(state, "job %s requires %d of %s > capacity %d" % (ids[i], u, rn, caps[ridx[rn]]))
            if u > 0:
                rl.append((ridx[rn], u))
        req.append(rl)

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    # Kahn
    topo = []
    deg = indeg[:]
    stack = [i for i in range(n) if deg[i] == 0]
    while stack:
        x = stack.pop()
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if deg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc[:6]))
    rank = [0] * n
    for k, x in enumerate(topo):
        rank[x] = k

    # heads / tails / lower bound
    head = [0] * n
    for x in topo:
        h = rel[x]
        for p in preds[x]:
            v = head[p] + dur[p]
            if v > h:
                h = v
        head[x] = h
    tail = [0] * n
    for x in reversed(topo):
        t = 0
        for s in succs[x]:
            if tail[s] > t:
                t = tail[s]
        tail[x] = t + dur[x]
    LB = 0
    for x in range(n):
        LB = max(LB, head[x] + tail[x])
    for r in range(R):
        tot = 0
        mr = None
        for x in range(n):
            for (rr, u) in req[x]:
                if rr == r and dur[x] > 0:
                    tot += u * dur[x]
                    mr = head[x] if mr is None else min(mr, head[x])
        if tot > 0 and caps[r] > 0:
            LB = max(LB, mr + (tot + caps[r] - 1) // caps[r])

    H = max(rel) + sum(dur) + 2
    order_req = [r for r in range(n)]

    def decode(order):
        avail = [[caps[r]] * H for r in range(R)]
        start = [0] * n
        ms = 0
        for j in order:
            t = rel[j]
            for p in preds[j]:
                v = start[p] + dur[p]
                if v > t:
                    t = v
            d = dur[j]
            rq = req[j]
            if d > 0 and rq:
                while True:
                    ok = True
                    k = t
                    end = t + d
                    while k < end:
                        bad = False
                        for (r, u) in rq:
                            if avail[r][k] < u:
                                bad = True
                                break
                        if bad:
                            ok = False
                            t = k + 1
                            break
                        k += 1
                    if ok:
                        break
                for (r, u) in rq:
                    a = avail[r]
                    for k in range(t, t + d):
                        a[k] -= u
            start[j] = t
            if t + d > ms:
                ms = t + d
        return start, ms

    def backward(start, M):
        order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -start[j], -rank[j]))
        avail = [[caps[r]] * H for r in range(R)]
        ns = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if ns[s] < lf:
                    lf = ns[s]
            d = dur[j]
            t = lf - d
            rq = req[j]
            if d > 0 and rq:
                while True:
                    if t < rel[j]:
                        return None
                    ok = True
                    k = t + d - 1
                    while k >= t:
                        bad = False
                        for (r, u) in rq:
                            if avail[r][k] < u:
                                bad = True
                                break
                        if bad:
                            ok = False
                            t = k - d
                            break
                        k -= 1
                    if ok:
                        break
                for (r, u) in rq:
                    a = avail[r]
                    for k in range(t, t + d):
                        a[k] -= u
            if t < rel[j]:
                return None
            ns[j] = t
        return ns

    def to_list(start):
        return sorted(range(n), key=lambda j: (start[j], rank[j]))

    def fbi(start, ms):
        while True:
            bs = backward(start, ms)
            if bs is None:
                return start, ms
            s2, m2 = decode(to_list(bs))
            if m2 < ms:
                start, ms = s2, m2
            else:
                if m2 == ms:
                    start = s2
                return start, ms

    best = {"ms": None, "start": None}

    def consider(start, ms):
        if best["ms"] is None or ms < best["ms"]:
            best["ms"] = ms
            best["start"] = start[:]

    def build_list(key):
        deg2 = indeg[:]
        elig = [i for i in range(n) if deg2[i] == 0]
        out = []
        while elig:
            b = min(elig, key=lambda x: (key[x], rank[x]))
            elig.remove(b)
            out.append(b)
            for s in succs[b]:
                deg2[s] -= 1
                if deg2[s] == 0:
                    elig.append(s)
        return out

    rng = random.Random(12345)

    def build_random(key):
        deg2 = indeg[:]
        elig = [i for i in range(n) if deg2[i] == 0]
        out = []
        while elig:
            mx = max(key[x] for x in elig)
            ws = [(mx - key[x] + 1) ** 2 for x in elig]
            tot = sum(ws)
            v = rng.random() * tot
            acc = 0
            pick = len(elig) - 1
            for q, w in enumerate(ws):
                acc += w
                if v < acc:
                    pick = q
                    break
            b = elig.pop(pick)
            out.append(b)
            for s in succs[b]:
                deg2[s] -= 1
                if deg2[s] == 0:
                    elig.append(s)
        return out

    # total successors
    desc = [set() for _ in range(n)]
    for x in reversed(topo):
        for s in succs[x]:
            desc[x].add(s)
            desc[x] |= desc[s]
    work = [sum(u for (r, u) in req[x]) * dur[x] for x in range(n)]
    keys = [
        [-tail[x] for x in range(n)],
        [-(tail[x] + head[x]) for x in range(n)],
        [head[x] for x in range(n)],
        [-len(desc[x]) for x in range(n)],
        [-(work[x] + sum(work[s] for s in succs[x])) for x in range(n)],
        [rel[x] - tail[x] for x in range(n)],
        [-dur[x] for x in range(n)],
    ]
    for key in keys:
        s, m = decode(build_list(key))
        s, m = fbi(s, m)
        consider(s, m)
        if best["ms"] <= LB or time.perf_counter() - t0 > budget:
            break

    lft_key = keys[0]
    cur_start = best["start"][:]
    cur_ms = best["ms"]
    cur_list = to_list(cur_start)
    it = 0
    stall = 0
    while best["ms"] > LB and time.perf_counter() - t0 < budget:
        it += 1
        if it % 3 == 0:
            s, m = decode(build_random(lft_key if rng.random() < 0.6 else keys[rng.randrange(len(keys))]))
            s, m = fbi(s, m)
            consider(s, m)
            if m < cur_ms:
                cur_start, cur_ms, cur_list = s, m, to_list(s)
            continue
        lst = cur_list[:]
        nmoves = 1 + (rng.random() < 0.3) + (stall > 50)
        for _ in range(nmoves):
            i = rng.randrange(n)
            j = lst[i]
            del lst[i]
            pos = {x: q for q, x in enumerate(lst)}
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = len(lst)
            for s_ in succs[j]:
                if pos[s_] < hi:
                    hi = pos[s_]
            lst.insert(rng.randint(lo, hi), j)
        s, m = decode(lst)
        s, m = fbi(s, m)
        consider(s, m)
        if m <= cur_ms:
            if m < cur_ms:
                stall = 0
            else:
                stall += 1
            cur_start, cur_ms, cur_list = s, m, to_list(s)
        else:
            stall += 1
        if stall > 200:
            stall = 0
            cur_start = best["start"][:]
            cur_ms = best["ms"]
            cur_list = to_list(cur_start)

    st = best["start"]
    out = {}
    for i in range(n):
        if ids[i] not in out:
            out[ids[i]] = int(st[i])
    state["output"] = {"status": "ok", "start": out}
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def schedule_jobs(state, params):
    t0 = time.perf_counter()
    budget = 1.0
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(res[r]) for r in rnames]
    R = len(rnames)
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        if s not in jidx:
            jidx[s] = i
    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    preds = []
    req = []
    for i, j in enumerate(jobs):
        ps = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], p))
            k = jidx[p]
            if k not in ps:
                ps.append(k)
        preds.append(ps)
        rq = []
        for rn, u in (j.get("requires") or {}).items():
            if rn not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            if u > cap[ridx[rn]]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, rn, cap[ridx[rn]]))
            if u > 0:
                rq.append((ridx[rn], u))
        req.append(rq)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        left = [ids[i] for i in range(n) if indeg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(left[:6]))
    trank = [0] * n
    for k, x in enumerate(topo):
        trank[x] = k
    es = [0] * n
    for x in topo:
        e = rel[x]
        for p in preds[x]:
            e = max(e, es[p] + dur[p])
        es[x] = e
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            m = max(m, tail[s])
        tail[x] = dur[x] + m
    nsucc_all = [0] * n
    desc = [set() for _ in range(n)]
    for x in reversed(topo):
        for s in succs[x]:
            desc[x].add(s)
            desc[x] |= desc[s]
        nsucc_all[x] = len(desc[x])
    LB = max(es[i] + tail[i] for i in range(n))
    for r in range(R):
        if cap[r] <= 0:
            continue
        for th in set(es):
            work = 0
            for i in range(n):
                if es[i] >= th and dur[i] > 0:
                    for (rr, u) in req[i]:
                        if rr == r:
                            work += u * dur[i]
            if work:
                LB = max(LB, th + (work + cap[r] - 1) // cap[r])
    H0 = max(rel) + sum(dur) + max(dur) + 2

    def fits(usage, t, d, rq):
        for tt in range(t, t + d):
            for (r, u) in rq:
                if usage[r][tt] + u > cap[r]:
                    return tt
        return -1

    def sgs(order):
        H = H0
        usage = [[0] * H for _ in range(R)]
        st = [0] * n
        mk = 0
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = st[p] + dur[p]
                if f > t:
                    t = f
            d = dur[j]
            rq = req[j]
            if d > 0 and rq:
                while True:
                    if t + d > H:
                        ext = t + d - H + H0
                        for r in range(R):
                            usage[r].extend([0] * ext)
                        H += ext
                    c = fits(usage, t, d, rq)
                    if c < 0:
                        break
                    t = c + 1
                for (r, u) in rq:
                    ur = usage[r]
                    for tt in range(t, t + d):
                        ur[tt] += u
            st[j] = t
            if t + d > mk:
                mk = t + d
        return st, mk

    def backward(st, M):
        order = sorted(range(n), key=lambda j: (-(st[j] + dur[j]), -trank[j]))
        usage = [[0] * (M + 1) for _ in range(R)]
        ns = [0] * n
        for j in order:
            d = dur[j]
            ls = M - d
            for s in succs[j]:
                v = ns[s] - d
                if v < ls:
                    ls = v
            if ls < rel[j]:
                return None
            rq = req[j]
            if d > 0 and rq:
                t = ls
                while True:
                    if t < rel[j]:
                        return None
                    c = fits(usage, t, d, rq)
                    if c < 0:
                        break
                    t = c - d
                for (r, u) in rq:
                    ur = usage[r]
                    for tt in range(t, t + d):
                        ur[tt] += u
                ns[j] = t
            else:
                ns[j] = ls
        return ns

    def improve(st, mk):
        best_order = None
        for _ in range(4):
            ns = backward(st, mk)
            if ns is None:
                break
            order = sorted(range(n), key=lambda j: (ns[j], trank[j]))
            st2, mk2 = sgs(order)
            if mk2 < mk:
                st, mk, best_order = st2, mk2, order
            else:
                if mk2 == mk:
                    st, best_order = st2, order
                break
        return st, mk, best_order

    def build(key):
        deg = [len(preds[i]) for i in range(n)]
        h = [(-key[i], trank[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(h, (-key[s], trank[s], s))
        return out

    best = {"st": None, "mk": None, "order": None}

    def evaluate(order):
        st, mk = sgs(order)
        st2, mk2, o2 = improve(st, mk)
        if o2 is not None:
            order = o2
            st, mk = st2, mk2
        if best["mk"] is None or mk < best["mk"]:
            best["st"], best["mk"], best["order"] = st, mk, order
        return mk, order

    rulekeys = [
        [tail[i] for i in range(n)],
        [-(LB - tail[i]) for i in range(n)],
        [tail[i] * 1000 - es[i] for i in range(n)],
        [-es[i] * 1000 + tail[i] for i in range(n)],
        [nsucc_all[i] * 1000 + tail[i] for i in range(n)],
        [tail[i] * 1000 + sum(u for _, u in req[i]) * dur[i] for i in range(n)],
        [-(es[i] + 0.0) for i in range(n)],
        [tail[i] - es[i] for i in range(n)],
    ]
    for k in rulekeys:
        evaluate(build(k))
        if best["mk"] <= LB:
            break
    rng = random.Random(12345)
    cur_order = list(best["order"])
    cur_mk = best["mk"]
    stall = 0
    while best["mk"] > LB and time.perf_counter() - t0 < budget:
        if stall > 60 + 3 * n:
            base = rulekeys[rng.randrange(len(rulekeys))]
            spread = (max(base) - min(base)) or 1
            key = [base[i] + rng.random() * spread * 0.5 for i in range(n)]
            mk, order = evaluate(build(key))
            cur_order, cur_mk = order, mk
            stall = 0
            continue
        order = list(cur_order)
        pos = {x: k for k, x in enumerate(order)}
        x = order[rng.randrange(n)]
        lo = max([pos[p] for p in preds[x]], default=-1) + 1
        hi = min([pos[s] for s in succs[x]], default=n) - 1
        if hi <= lo:
            stall += 1
            continue
        k = pos[x]
        nk = rng.randint(lo, hi)
        if nk == k:
            nk = lo if k != lo else hi
        order.pop(k)
        order.insert(nk, x)
        if rng.random() < 0.3:
            pos = {y: kk for kk, y in enumerate(order)}
            y = order[rng.randrange(n)]
            lo2 = max([pos[p] for p in preds[y]], default=-1) + 1
            hi2 = min([pos[s] for s in succs[y]], default=n) - 1
            if hi2 > lo2:
                k2 = pos[y]
                order.pop(k2)
                nk2 = rng.randint(lo2, hi2 - (1 if hi2 > k2 else 0)) if hi2 > lo2 else lo2
                nk2 = max(lo2 if lo2 < k2 else lo2 - 1, min(nk2, hi2))
                order.insert(nk2, y)
                pp = {z: kk for kk, z in enumerate(order)}
                ok = all(pp[p] < pp[z] for z in range(n) for p in preds[z])
                if not ok:
                    order.pop(nk2)
                    order.insert(k2, y)
        mk, order2 = evaluate(order)
        if mk < cur_mk:
            cur_order, cur_mk = order2, mk
            stall = 0
        elif mk == cur_mk:
            cur_order = order2
            stall += 1
        else:
            stall += 1

    st = best["st"]
    ok = True
    for i in range(n):
        if st[i] < rel[i]:
            ok = False
        for p in preds[i]:
            if st[i] < st[p] + dur[p]:
                ok = False
    if ok:
        M = max(st[i] + dur[i] for i in range(n))
        use = [[0] * (M + 1) for _ in range(R)]
        for i in range(n):
            for (r, u) in req[i]:
                for tt in range(st[i], st[i] + dur[i]):
                    use[r][tt] += u
                    if use[r][tt] > cap[r]:
                        ok = False
    if not ok:
        t = 0
        st = [0] * n
        for x in topo:
            t = max(t, rel[x])
            st[x] = t
            t += dur[x]
    out = {}
    for i in range(n):
        if ids[i] not in out:
            out[ids[i]] = int(st[i])
    state["output"] = {"status": "ok", "start": out}
    state["lb_internal"] = LB
    return state

import time
import random
import math


def _validate(inp):
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = []
    idx = {}
    for k, jb in enumerate(jobs):
        jid = str(jb.get("id"))
        ids.append(jid)
        if jid not in idx:
            idx[jid] = k
    for jb in jobs:
        for p in (jb.get("after") or []):
            if str(p) not in idx:
                return None, "job %s references unknown job %s" % (jb.get("id"), p)
        for r, u in (jb.get("requires") or {}).items():
            if r not in resources:
                return None, "job %s references unknown resource %s" % (jb.get("id"), r)
            if u > resources[r]:
                return None, "job %s requires %s units of %s > capacity %s" % (
                    jb.get("id"), u, r, resources[r])
    n = len(jobs)
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for k, jb in enumerate(jobs):
        seen = set()
        for p in (jb.get("after") or []):
            pi = idx[str(p)]
            if pi in seen:
                continue
            seen.add(pi)
            preds[k].append(pi)
            succs[pi].append(k)
    indeg = [len(preds[k]) for k in range(n)]
    queue = [k for k in range(n) if indeg[k] == 0]
    topo = []
    h = 0
    while h < len(queue):
        x = queue[h]
        h += 1
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) < n:
        cyc = [ids[k] for k in range(n) if indeg[k] > 0]
        return None, "precedence cycle among " + ", ".join(cyc[:10])
    return {"ids": ids, "preds": preds, "succs": succs, "topo": topo}, None


def _sequential(n, dur, rel, preds, topo):
    st = [0] * n
    cur = 0
    for j in topo:
        t = max(cur, rel[j])
        for p in preds[j]:
            t = max(t, st[p] + dur[p])
        st[j] = t
        cur = t + dur[j]
    return st


def _check(n, dur, rel, preds, req, cap, st):
    for j in range(n):
        if st[j] < rel[j]:
            return False
        for p in preds[j]:
            if st[j] < st[p] + dur[p]:
                return False
    usage = {}
    for j in range(n):
        if dur[j] <= 0:
            continue
        for (r, u) in req[j]:
            for t in range(st[j], st[j] + dur[j]):
                key = (r, t)
                usage[key] = usage.get(key, 0) + u
                if usage[key] > cap[r]:
                    return False
    return True


def solve(state, params):
    t0 = time.perf_counter()
    budget = 0.9
    inp = state["input"]
    info, reason = _validate(inp)
    if info is None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    n = len(jobs)
    ids = info["ids"]
    preds = info["preds"]
    succs = info["succs"]
    topo = info["topo"]
    rank = [0] * n
    for i, j in enumerate(topo):
        rank[j] = i
    dur = [max(0, int(jb.get("duration", 0))) for jb in jobs]
    rel = [max(0, int(jb.get("release", 0))) for jb in jobs]
    req = []
    for jb in jobs:
        lst = []
        for r, u in (jb.get("requires") or {}).items():
            if u > 0:
                lst.append((ridx[r], int(u)))
        req.append(lst)

    # fallback
    fb = _sequential(n, dur, rel, preds, topo)
    fb_ms = max([fb[j] + dur[j] for j in range(n)] + [0])

    def emit(st):
        state["output"] = {"status": "ok",
                           "start": {ids[j]: int(st[j]) for j in range(n)}}

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    try:
        tail = [0] * n
        for j in reversed(topo):
            m = 0
            for s in succs[j]:
                if tail[s] > m:
                    m = tail[s]
            tail[j] = dur[j] + m
        es = [0] * n
        for j in topo:
            t = rel[j]
            for p in preds[j]:
                if es[p] + dur[p] > t:
                    t = es[p] + dur[p]
            es[j] = t
        LB = max(es[j] + tail[j] for j in range(n))
        for r in range(len(cap)):
            energy = 0
            mr = None
            for j in range(n):
                if dur[j] > 0:
                    for (rr, u) in req[j]:
                        if rr == r:
                            energy += u * dur[j]
                            if mr is None or es[j] < mr:
                                mr = es[j]
            if energy > 0 and cap[r] > 0:
                LB = max(LB, mr + (energy + cap[r] - 1) // cap[r])
        nsucc = [0] * n
        for j in reversed(topo):
            reach = set()
            stack = list(succs[j])
            while stack:
                x = stack.pop()
                if x in reach:
                    continue
                reach.add(x)
                stack.extend(succs[x])
            nsucc[j] = len(reach)

        H = max(rel) + sum(dur) + 2
        R = len(cap)

        def fwd(order):
            use = [[0] * H for _ in range(R)]
            st = [0] * n
            fin = [0] * n
            for j in order:
                t = rel[j]
                for p in preds[j]:
                    if fin[p] > t:
                        t = fin[p]
                d = dur[j]
                rq = req[j]
                if d > 0 and rq:
                    while True:
                        ok = True
                        for (r, u) in rq:
                            ur = use[r]
                            c = cap[r] - u
                            for tau in range(t + d - 1, t - 1, -1):
                                if ur[tau] > c:
                                    t = tau + 1
                                    ok = False
                                    break
                            if not ok:
                                break
                        if ok:
                            break
                    for (r, u) in rq:
                        ur = use[r]
                        for tau in range(t, t + d):
                            ur[tau] += u
                st[j] = t
                fin[j] = t + d
            return st, max(fin)

        def bwd(order, T):
            use = [[0] * (T + 1) for _ in range(R)]
            bst = [None] * n
            for j in order:
                lf = T
                for s in succs[j]:
                    if bst[s] is not None and bst[s] < lf:
                        lf = bst[s]
                d = dur[j]
                t = lf - d
                if t < 0:
                    return None
                rq = req[j]
                if d > 0 and rq:
                    while True:
                        ok = True
                        for (r, u) in rq:
                            ur = use[r]
                            c = cap[r] - u
                            for tau in range(t, t + d):
                                if ur[tau] > c:
                                    t = tau - d
                                    ok = False
                                    break
                            if not ok:
                                break
                        if t < 0:
                            return None
                        if ok:
                            break
                    for (r, u) in rq:
                        ur = use[r]
                        for tau in range(t, t + d):
                            ur[tau] += u
                bst[j] = t
            return bst

        def norm(st):
            return sorted(range(n), key=lambda j: (st[j], rank[j]))

        def fbi(st, ms):
            for _ in range(20):
                ob = sorted(range(n), key=lambda j: (-(st[j] + dur[j]), -rank[j]))
                bst = bwd(ob, ms)
                if bst is None:
                    break
                of = sorted(range(n), key=lambda j: (bst[j], rank[j]))
                st2, ms2 = fwd(of)
                if ms2 < ms:
                    st, ms = st2, ms2
                else:
                    break
            return st, ms

        rng = random.Random(12345)

        def sample(prio, noise):
            indeg = [len(preds[j]) for j in range(n)]
            elig = [j for j in range(n) if indeg[j] == 0]
            order = []
            while elig:
                if noise <= 0:
                    bi = max(range(len(elig)), key=lambda i: (prio[elig[i]], -rank[elig[i]]))
                else:
                    bi = max(range(len(elig)), key=lambda i: prio[elig[i]] + noise * rng.random())
                j = elig[bi]
                elig[bi] = elig[-1]
                elig.pop()
                order.append(j)
                for s in succs[j]:
                    indeg[s] -= 1
                    if indeg[s] == 0:
                        elig.append(s)
            return order

        maxtail = max(tail) + 1
        maxes = max(es) + 1
        rules = [
            [tail[j] for j in range(n)],
            [-es[j] for j in range(n)],
            [tail[j] - es[j] for j in range(n)],
            [tail[j] + 0.5 * nsucc[j] for j in range(n)],
            [nsucc[j] + tail[j] / maxtail for j in range(n)],
            [-(es[j] + 0.0) + tail[j] / (maxtail + 1.0) for j in range(n)],
        ]

        best_st, best_ms = fb, fb_ms

        def consider(order):
            st, ms = fwd(order)
            st, ms = fbi(st, ms)
            return st, ms

        for pr in rules:
            st, ms = consider(sample(pr, 0))
            if ms < best_ms:
                best_st, best_ms = st, ms
            if best_ms <= LB:
                break

        def scale_of(pr):
            return (max(pr) - min(pr)) + 1.0

        cur_order = norm(best_st)
        cur_ms = best_ms
        stall = 0
        it = 0
        while best_ms > LB and time.perf_counter() - t0 < budget:
            it += 1
            if stall > 30 + 6 * n:
                stall = 0
                if rng.random() < 0.5:
                    pr = rules[rng.randrange(len(rules))]
                    o = sample(pr, scale_of(pr) * rng.choice([0.2, 0.5, 1.0]))
                    st, ms = consider(o)
                else:
                    o = norm(best_st)
                    for _ in range(rng.randint(2, 4)):
                        i = rng.randrange(n)
                        j = o[i]
                        pos = {x: k for k, x in enumerate(o)}
                        lo = max([pos[p] + 1 for p in preds[j]] + [0])
                        hi = min([pos[s] for s in succs[j]] + [n])
                        o2 = o[:i] + o[i + 1:]
                        o2.insert(rng.randint(lo, hi - 1), j)
                        o = o2
                    st, ms = consider(o)
                if ms < best_ms:
                    best_st, best_ms = st, ms
                cur_order = norm(st)
                cur_ms = ms
                continue
            o = cur_order
            pos = [0] * n
            for k, x in enumerate(o):
                pos[x] = k
            i = rng.randrange(n)
            j = o[i]
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = n
            for s in succs[j]:
                if pos[s] < hi:
                    hi = pos[s]
            if hi - 1 <= lo:
                stall += 1
                continue
            k = rng.randint(lo, hi - 1)
            if k == i:
                stall += 1
                continue
            o2 = o[:i] + o[i + 1:]
            o2.insert(k, j)
            st, ms = fwd(o2)
            if ms < cur_ms:
                st, ms = fbi(st, ms)
                cur_order = norm(st)
                cur_ms = ms
                stall = 0
                if ms < best_ms:
                    best_st, best_ms = st, ms
            elif ms == cur_ms:
                cur_order = norm(st)
                stall += 1
            else:
                stall += 1

        if _check(n, dur, rel, preds, req, cap, best_st):
            emit(best_st)
        else:
            emit(fb)
    except Exception:
        emit(fb)
    return state

import time, random, heapq, json


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 0.9
    inp = state.get("input") or {}
    if isinstance(inp, str):
        inp = json.loads(inp)
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    rnames = list(res.keys())
    rix = {r: k for k, r in enumerate(rnames)}
    caps = [int(res[r]) for r in rnames]
    nr = len(rnames)

    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    preds = [[] for _ in range(n)]
    req = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        seen = set()
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], p))
            pi = idx[p]
            if pi not in seen:
                seen.add(pi)
                preds[i].append(pi)
        for r, u in (j.get("requires") or {}).items():
            if r not in rix:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], r))
            u = int(u)
            k = rix[r]
            if u > caps[k]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, r, caps[k]))
            if u > 0 and dur[i] > 0:
                req[i].append((k, u))

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    topo = []
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    h = 0
    while h < len(dq):
        x = dq[h]
        h += 1
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if deg[i] > 0][:6]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc))
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for r_, i in enumerate(topo):
        rank[i] = r_

    # heads / tails / lower bound
    est = [0] * n
    for i in topo:
        t = rel[i]
        for p in preds[i]:
            e = est[p] + dur[p]
            if e > t:
                t = e
        est[i] = t
    q = [0] * n
    for i in reversed(topo):
        m = 0
        for s in succs[i]:
            if q[s] > m:
                m = q[s]
        q[i] = dur[i] + m
    LB = max(est[i] + q[i] for i in range(n))
    for k in range(nr):
        en = 0
        mr = None
        for i in range(n):
            for (kk, u) in req[i]:
                if kk == k:
                    en += u * dur[i]
                    mr = rel[i] if mr is None else min(mr, rel[i])
        if en > 0 and caps[k] > 0:
            LB = max(LB, (mr or 0) + (en + caps[k] - 1) // caps[k])

    H = max(rel) + sum(dur) + 3

    def sgs(order, pr, rl):
        usage = [[0] * H for _ in range(nr)]
        st = [0] * n
        ms = 0
        for i in order:
            t = rl[i] if rl is not None else 0
            for p in pr[i]:
                e = st[p] + dur[p]
                if e > t:
                    t = e
            d = dur[i]
            rq = req[i]
            if rq:
                while True:
                    moved = False
                    for (k, u) in rq:
                        us = usage[k]
                        lim = caps[k] - u
                        tt = t + d - 1
                        while tt >= t:
                            if us[tt] > lim:
                                break
                            tt -= 1
                        if tt >= t:
                            t = tt + 1
                            moved = True
                            break
                    if not moved:
                        break
                for (k, u) in rq:
                    us = usage[k]
                    for tt in range(t, t + d):
                        us[tt] += u
            st[i] = t
            if t + d > ms:
                ms = t + d
        return st, ms

    def norm(st):
        return sorted(range(n), key=lambda i: (st[i], rank[i]))

    def fbi(order, rounds=3):
        st, ms = sgs(order, preds, rel)
        best_st, best_ms = st, ms
        for _ in range(rounds):
            border = sorted(range(n), key=lambda i: (best_st[i] + dur[i], rank[i]), reverse=True)
            rs, _ = sgs(border, succs, None)
            forder = sorted(range(n), key=lambda i: (-(rs[i] + dur[i]), rank[i]))
            st2, ms2 = sgs(forder, preds, rel)
            if ms2 < best_ms:
                best_st, best_ms = st2, ms2
            else:
                if ms2 == best_ms:
                    best_st = st2
                break
        return best_st, best_ms

    def build(key):
        dg = indeg[:]
        hp = [(key[i], rank[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, _, x = heapq.heappop(hp)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(hp, (key[s], rank[s], s))
        return out

    desc = [0] * n
    dsets = [set() for _ in range(n)]
    for i in reversed(topo):
        sset = set()
        for s in succs[i]:
            sset.add(s)
            sset |= dsets[s]
        dsets[i] = sset
        desc[i] = len(sset)
    work = [dur[i] * sum(u / max(1, caps[k]) for (k, u) in req[i]) for i in range(n)]
    grpw = [dur[i] + sum(dur[s] for s in succs[i]) for i in range(n)]

    rng = random.Random(1234567)
    keys = [
        [-q[i] for i in range(n)],
        [est[i] - q[i] for i in range(n)],
        [(est[i], -q[i]) for i in range(n)],
        [(-desc[i], -q[i]) for i in range(n)],
        [-grpw[i] for i in range(n)],
        [(-(q[i] + work[i]), est[i]) for i in range(n)],
        [rel[i] - q[i] for i in range(n)],
    ]

    best = {"ms": None, "st": None}
    pop = []
    seen = set()

    def consider(st, ms):
        if best["ms"] is None or ms < best["ms"]:
            best["ms"] = ms
            best["st"] = st[:]
        order = norm(st)
        tk = tuple(order)
        return order, tk

    def add(st, ms):
        order, tk = consider(st, ms)
        if tk in seen:
            return
        seen.add(tk)
        pop.append([ms, order])

    for key in keys:
        st, ms = fbi(build(key))
        add(st, ms)
        if best["ms"] <= LB:
            break

    POP = 40
    while len(pop) < POP and best["ms"] > LB and time.perf_counter() - T0 < BUDGET * 0.35:
        a = 0.1 + rng.random() * 0.6
        key = [(est[i] - q[i]) * (1 + a * (rng.random() - 0.5)) + rng.random() * 2 * a for i in range(n)]
        st, ms = fbi(build(key))
        add(st, ms)

    predsets = [set(p) for p in preds]
    it = 0
    while best["ms"] > LB and len(pop) >= 2:
        if time.perf_counter() - T0 > BUDGET:
            break
        it += 1

        def tour():
            a = pop[rng.randrange(len(pop))]
            b = pop[rng.randrange(len(pop))]
            return a if a[0] <= b[0] else b
        m = tour()[1]
        f = tour()[1]
        q1 = rng.randrange(n)
        q2 = rng.randrange(q1, n + 1)
        taken = [False] * n
        child = []
        for x in m[:q1]:
            taken[x] = True
            child.append(x)
        for x in f:
            if len(child) >= q2:
                break
            if not taken[x]:
                taken[x] = True
                child.append(x)
        for x in m:
            if not taken[x]:
                taken[x] = True
                child.append(x)
        pm = 0.05 + 0.1 * rng.random()
        for p in range(n - 1):
            if rng.random() < pm:
                a, b = child[p], child[p + 1]
                if a not in predsets[b]:
                    child[p], child[p + 1] = b, a
        if rng.random() < 0.6:
            st, ms = fbi(child, 2)
        else:
            st, ms = sgs(child, preds, rel)
        order, tk = consider(st, ms)
        if tk in seen:
            continue
        wi = max(range(len(pop)), key=lambda z: pop[z][0])
        if ms <= pop[wi][0]:
            seen.discard(tuple(pop[wi][1]))
            seen.add(tk)
            pop[wi] = [ms, order]

    st = best["st"]

    def valid(st):
        for i in range(n):
            if st[i] < rel[i]:
                return False
            for p in preds[i]:
                if st[i] < st[p] + dur[p]:
                    return False
        usage = [dict() for _ in range(nr)]
        for i in range(n):
            for (k, u) in req[i]:
                for t in range(st[i], st[i] + dur[i]):
                    v = usage[k].get(t, 0) + u
                    if v > caps[k]:
                        return False
                    usage[k][t] = v
        return True

    if st is None or not valid(st):
        st = [0] * n
        cur = 0
        for i in topo:
            s = max(cur, rel[i])
            st[i] = s
            cur = s + dur[i]

    state["output"] = {"status": "ok", "start": {ids[i]: int(st[i]) for i in range(n)}}
    return state

import time
import random
from collections import deque


def validate(state, params):
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    reason = None
    for j in jobs:
        jid = str(j.get("id"))
        for p in (j.get("after") or []):
            if str(p) not in idset:
                reason = "job %s references unknown job %s" % (jid, p)
                break
        if reason:
            break
        for r, u in (j.get("requires") or {}).items():
            if r not in resources:
                reason = "job %s references unknown resource %s" % (jid, r)
                break
            try:
                if int(u) > int(resources[r]):
                    reason = "job %s requires %s units of %s > capacity %s" % (jid, u, r, resources[r])
                    break
            except Exception:
                pass
        if reason:
            break
    if reason is None:
        # cycle detection (Kahn)
        idx = {}
        for k, i in enumerate(ids):
            idx[i] = k
        n = len(ids)
        succ = [set() for _ in range(n)]
        indeg = [0] * n
        for k, j in enumerate(jobs):
            ps = set(str(p) for p in (j.get("after") or []))
            for p in ps:
                pi = idx[p]
                if k not in succ[pi]:
                    succ[pi].add(k)
                    indeg[k] += 1
        q = deque([k for k in range(n) if indeg[k] == 0])
        seen = 0
        while q:
            u = q.popleft()
            seen += 1
            for v in succ[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        if seen < n:
            cyc = [ids[k] for k in range(n) if indeg[k] > 0][:5]
            reason = "precedence cycle among " + ", ".join(cyc)
    if reason is not None:
        state["feasible"] = False
        state["output"] = {"status": "infeasible", "reason": reason}
    else:
        state["feasible"] = True
    return state


def solve(state, params):
    t0 = time.perf_counter()
    budget = 0.9
    inp = state["input"]
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    idx = {}
    for k, i in enumerate(ids):
        idx[i] = k
    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    R = len(rnames)
    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    req = []
    for j in jobs:
        lst = []
        for r, u in (j.get("requires") or {}).items():
            u = int(u)
            if u > 0:
                lst.append((ridx[r], u))
        req.append(lst)
    preds = [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for k in range(n):
        for p in preds[k]:
            succs[p].append(k)
    H = max(rel) + sum(dur) + 2

    # topological order
    indeg = [len(preds[k]) for k in range(n)]
    q = deque([k for k in range(n) if indeg[k] == 0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in succs[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    head = [0] * n
    for u in topo:
        h = rel[u]
        for p in preds[u]:
            if head[p] + dur[p] > h:
                h = head[p] + dur[p]
        head[u] = h
    tail = [0] * n  # longest path from start of u to end (incl dur[u])
    for u in reversed(topo):
        t = 0
        for s in succs[u]:
            if tail[s] > t:
                t = tail[s]
        tail[u] = dur[u] + t
    LB = max(head[k] + tail[k] for k in range(n))
    # resource energy bound
    for r in range(R):
        items = []
        for k in range(n):
            if dur[k] > 0:
                for (rr, u) in req[k]:
                    if rr == r:
                        items.append((head[k], dur[k] * u))
        if not items:
            continue
        items.sort()
        E = 0
        for i in range(len(items) - 1, -1, -1):
            E += items[i][1]
            T = items[i][0]
            b = T + (E + cap[r] - 1) // cap[r]
            if b > LB:
                LB = b
    nsucc_all = [0] * n
    for u in reversed(topo):
        s = set()
        for v in succs[u]:
            s.add(v)
        nsucc_all[u] = len(succs[u]) + sum(nsucc_all[v] for v in succs[u])

    def sgs(prio, fwd):
        P = preds if fwd else succs
        S = succs if fwd else preds
        npred = [len(P[k]) for k in range(n)]
        usage = [[0] * H for _ in range(R)]
        start = [0] * n
        finish = [0] * n
        elig = [k for k in range(n) if npred[k] == 0]
        M = 0
        while elig:
            bi = 0
            bp = prio[elig[0]]
            for i in range(1, len(elig)):
                pv = prio[elig[i]]
                if pv < bp:
                    bp = pv
                    bi = i
            j = elig[bi]
            elig[bi] = elig[-1]
            elig.pop()
            est = rel[j] if fwd else 0
            for p in P[j]:
                if finish[p] > est:
                    est = finish[p]
            d = dur[j]
            rq = req[j]
            t = est
            if d > 0 and rq:
                while True:
                    bad = -1
                    for (r, u) in rq:
                        ur = usage[r]
                        c = cap[r] - u
                        for s in range(t + d - 1, t - 1, -1):
                            if ur[s] > c:
                                if s > bad:
                                    bad = s
                                break
                    if bad < 0:
                        break
                    t = bad + 1
                for (r, u) in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] += u
            start[j] = t
            finish[j] = t + d
            if t + d > M:
                M = t + d
            for v in S[j]:
                npred[v] -= 1
                if npred[v] == 0:
                    elig.append(v)
        return start, M

    rng = random.Random(12345)

    def evaluate(keys):
        st, M = sgs(keys, True)
        best_st, bestM = st, M
        for _ in range(4):
            bprio = [-(st[k] + dur[k]) - 1e-6 * k for k in range(n)]
            rs, Mb = sgs(bprio, False)
            fprio = [Mb - rs[k] - dur[k] + 1e-6 * k for k in range(n)]
            st2, M2 = sgs(fprio, True)
            if M2 < bestM:
                best_st, bestM = st2, M2
                st = st2
            else:
                break
        return best_st, bestM

    best = None
    bestM = None

    def consider(st, M):
        nonlocal best, bestM
        if bestM is None or M < bestM:
            best, bestM = list(st), M

    lft = [-(tail[k]) for k in range(n)]
    rules = [
        [-tail[k] + 1e-4 * k for k in range(n)],
        [head[k] - tail[k] * 0.001 for k in range(n)],
        [-(tail[k] + head[k]) + 1e-4 * k for k in range(n)],
        [-nsucc_all[k] - 0.001 * tail[k] for k in range(n)],
        [lft[k] + 0.01 * head[k] for k in range(n)],
        [head[k] + 1e-4 * k for k in range(n)],
    ]
    for keys in rules:
        st, M = evaluate(keys)
        consider(st, M)
        if bestM <= LB:
            break

    if bestM > LB:
        cur = [best[k] + 1e-3 * rng.random() for k in range(n)]
        curM = bestM
        stall = 0
        while time.perf_counter() - t0 < budget:
            keys = list(cur)
            m = rng.random()
            nm = 1 if m < 0.5 else (2 if m < 0.8 else 3)
            for _ in range(nm):
                j = rng.randrange(n)
                if rng.random() < 0.6:
                    o = rng.randrange(n)
                    keys[j] = keys[o] + (rng.random() - 0.5) * 1.0
                else:
                    keys[j] = rng.random() * (curM + 1)
            if rng.random() < 0.1:
                for k in range(n):
                    keys[k] += rng.random() * 2.0
            st, M = evaluate(keys)
            if M <= curM:
                if M < curM:
                    stall = 0
                else:
                    stall += 1
                cur = [st[k] + 1e-3 * rng.random() for k in range(n)]
                curM = M
                consider(st, M)
                if bestM <= LB:
                    break
            else:
                stall += 1
            if stall > 150:
                stall = 0
                if rng.random() < 0.5:
                    cur = [best[k] + 1e-3 * rng.random() for k in range(n)]
                else:
                    cur = [best[k] + rng.random() * 3.0 for k in range(n)]
                curM = bestM

    state["output"] = {"status": "ok", "start": {ids[k]: int(best[k]) for k in range(n)}}
    state["makespan"] = bestM
    state["lower_bound"] = LB
    return state

import time, random, heapq, math


def _validate(inp):
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = {}
    for i, jb in enumerate(jobs):
        ids.setdefault(str(jb.get("id")), i)
    for jb in jobs:
        for p in jb.get("after") or []:
            if str(p) not in ids:
                return "job %s references unknown job %s" % (jb.get("id"), p)
        for r, u in (jb.get("requires") or {}).items():
            if r not in resources:
                return "job %s references unknown resource %s" % (jb.get("id"), r)
            if int(u) > int(resources[r]):
                return "job %s requires %s units of %s > capacity %s" % (jb.get("id"), u, r, resources[r])
    n = len(jobs)
    indeg = [0] * n
    succ = [[] for _ in range(n)]
    for j, jb in enumerate(jobs):
        for p in jb.get("after") or []:
            pi = ids[str(p)]
            succ[pi].append(j)
            indeg[j] += 1
    st = [j for j in range(n) if indeg[j] == 0]
    cnt = 0
    while st:
        x = st.pop()
        cnt += 1
        for y in succ[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                st.append(y)
    if cnt < n:
        cyc = [str(jobs[j].get("id")) for j in range(n) if indeg[j] > 0][:6]
        return "precedence cycle among " + ", ".join(cyc)
    return None


def validate_node(state, params):
    inp = state.get("input") or {}
    try:
        reason = _validate(inp)
    except Exception as e:
        reason = "malformed input: " + str(e)[:80]
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        state["is_infeasible"] = True
    else:
        state["is_infeasible"] = False
    return state


def solve_node(state, params):
    if state.get("is_infeasible"):
        return state
    T0 = time.perf_counter()
    BUDGET = 1.0
    inp = state["input"]
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    ids = {}
    for i, jb in enumerate(jobs):
        ids.setdefault(str(jb.get("id")), i)
    dur = [int(jb.get("duration", 0)) for jb in jobs]
    rel = [int(jb.get("release", 0)) for jb in jobs]
    preds = [sorted(set(ids[str(p)] for p in (jb.get("after") or []))) for jb in jobs]
    succs = [[] for _ in range(n)]
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
    req = []
    for j, jb in enumerate(jobs):
        lst = []
        if dur[j] > 0:
            for r, u in (jb.get("requires") or {}).items():
                u = int(u)
                if u > 0:
                    lst.append((ridx[r], u))
        req.append(lst)

    # topological order
    indeg = [len(preds[j]) for j in range(n)]
    topo = []
    st = [j for j in range(n) if indeg[j] == 0]
    while st:
        x = st.pop()
        topo.append(x)
        for y in succs[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                st.append(y)
    tpos = [0] * n
    for i, j in enumerate(topo):
        tpos[j] = i
    H = max(rel) + sum(dur) + 2
    R = len(cap)

    # CPM heads / tails
    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            f = es[p] + dur[p]
            if f > t:
                t = f
        es[j] = t
    cpm = max(es[j] + dur[j] for j in range(n))
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = m + dur[j]
    lb = cpm
    for r in range(R):
        e = 0
        mr = None
        for j in range(n):
            for (rr, u) in req[j]:
                if rr == r:
                    e += u * dur[j]
                    mr = es[j] if mr is None else min(mr, es[j])
        if e:
            lb = max(lb, mr + (e + cap[r] - 1) // cap[r])
    nsucc_all = [0] * n
    desc = [set() for _ in range(n)]
    for j in reversed(topo):
        for s in succs[j]:
            desc[j].add(s)
            desc[j] |= desc[s]
        nsucc_all[j] = len(desc[j])
    work = [sum(u * dur[j] / cap[r] for (r, u) in req[j]) for j in range(n)]

    def sgs(order):
        usage = [[0] * H for _ in range(R)]
        start = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = start[p] + dur[p]
                if f > t:
                    t = f
            rq = req[j]
            d = dur[j]
            if rq:
                ok = False
                while not ok:
                    ok = True
                    for s in range(t + d - 1, t - 1, -1):
                        for (r, u) in rq:
                            if usage[r][s] + u > cap[r]:
                                ok = False
                                break
                        if not ok:
                            t = s + 1
                            break
                for s in range(t, t + d):
                    for (r, u) in rq:
                        usage[r][s] += u
            start[j] = t
        return start

    def mk(start):
        return max(start[j] + dur[j] for j in range(n))

    def backward(start, M):
        order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -tpos[j]))
        usage = [[0] * (M + 1) for _ in range(R)]
        ns = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if ns[s] < lf:
                    lf = ns[s]
            d = dur[j]
            t = lf - d
            rq = req[j]
            if rq:
                ok = False
                while not ok:
                    if t < rel[j]:
                        return None
                    ok = True
                    for s in range(t, t + d):
                        for (r, u) in rq:
                            if usage[r][s] + u > cap[r]:
                                ok = False
                                break
                        if not ok:
                            t = s - d
                            break
                for s in range(t, t + d):
                    for (r, u) in rq:
                        usage[r][s] += u
            if t < rel[j]:
                return None
            ns[j] = t
        return ns

    def evaluate(order):
        s = sgs(order)
        m = mk(s)
        for _ in range(3):
            b = backward(s, m)
            if b is None:
                break
            o2 = sorted(range(n), key=lambda j: (b[j], tpos[j]))
            s2 = sgs(o2)
            m2 = mk(s2)
            if m2 < m:
                s, m = s2, m2
            else:
                if m2 == m:
                    s = s2
                break
        return m, s

    def keys_to_order(key):
        deg = [len(preds[j]) for j in range(n)]
        h = [(key[j], tpos[j], j) for j in range(n) if deg[j] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, _, x = heapq.heappop(h)
            out.append(x)
            for y in succs[x]:
                deg[y] -= 1
                if deg[y] == 0:
                    heapq.heappush(h, (key[y], tpos[y], y))
        return out

    rnd = random.Random(12345)
    best = [None, None]
    pool = []

    def consider(key):
        m, s = evaluate(keys_to_order(key))
        if best[0] is None or m < best[0]:
            best[0] = m
            best[1] = s
        nk = [s[j] + 0.001 * tpos[j] for j in range(n)]
        pool.append((m, rnd.random(), nk))
        return m

    L = cpm + 1
    rules = [
        [L - tail[j] for j in range(n)],
        [L - tail[j] + dur[j] for j in range(n)],
        [es[j] for j in range(n)],
        [-nsucc_all[j] for j in range(n)],
        [-(tail[j] + work[j]) for j in range(n)],
        [-work[j] for j in range(n)],
        [-dur[j] for j in range(n)],
        [rel[j] - tail[j] * 0.5 for j in range(n)],
    ]
    for k in rules:
        consider(k)
        if best[0] <= lb:
            break
    POP = 16
    it = 0
    while best[0] > lb and time.perf_counter() - T0 < BUDGET:
        it += 1
        pool.sort()
        del pool[POP:]
        if it % 5 == 0 or len(pool) < 2:
            base = rules[rnd.randrange(len(rules))]
            sc = max(1.0, max(abs(x) for x in base))
            sig = rnd.choice([0.1, 0.3, 0.6])
            key = [base[j] + rnd.gauss(0, sig * sc) for j in range(n)]
        else:
            a = pool[min(int(rnd.random() ** 2 * len(pool)), len(pool) - 1)][2]
            if rnd.random() < 0.5 and len(pool) > 1:
                b = pool[rnd.randrange(len(pool))][2]
                key = [a[j] if rnd.random() < 0.5 else b[j] for j in range(n)]
            else:
                key = list(a)
            mode = rnd.random()
            if mode < 0.4:
                sig = rnd.choice([0.5, 1.5, 3.0])
                for j in range(n):
                    if rnd.random() < 0.3:
                        key[j] += rnd.gauss(0, sig)
            elif mode < 0.7:
                i = rnd.randrange(n)
                k = rnd.randrange(n)
                key[i], key[k] = key[k], key[i]
            else:
                i = rnd.randrange(n)
                key[i] -= rnd.uniform(0.5, 8)
        consider(key)
    s = best[1]
    state["output"] = {"status": "ok",
                       "start": {str(jobs[j].get("id")): int(s[j]) for j in range(n)}}
    return state

import time
import math
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def _sgs(rank, P, S, rel, dur, req, caps, H, n, nres):
    indeg = [len(P[i]) for i in range(n)]
    heap = [(rank[i], i) for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    usage = [[0] * H for _ in range(nres)]
    start = [0] * n
    fin = [0] * n
    order = []
    while heap:
        _, i = heapq.heappop(heap)
        order.append(i)
        est = rel[i]
        for p in P[i]:
            if fin[p] > est:
                est = fin[p]
        d = dur[i]
        rq = req[i]
        t = est
        if d > 0 and rq:
            while True:
                bad = -1
                for u in range(t, t + d):
                    for (r, free, a) in rq:
                        if usage[r][u] > free:
                            bad = u
                            break
                    if bad >= 0:
                        break
                if bad < 0:
                    break
                t = bad + 1
            for u in range(t, t + d):
                for (r, free, a) in rq:
                    usage[r][u] += a
        start[i] = t
        fin[i] = t + d
        for s in S[i]:
            indeg[s] -= 1
            if indeg[s] == 0:
                heapq.heappush(heap, (rank[s], s))
    mk = max(fin) if n else 0
    return start, mk


def _valid(start, n, P, rel, dur, reqraw, caps):
    if len(start) != n:
        return False
    for i in range(n):
        if not isinstance(start[i], int) or start[i] < rel[i]:
            return False
        for p in P[i]:
            if start[i] < start[p] + dur[p]:
                return False
    events = {}
    for i in range(n):
        if dur[i] <= 0:
            continue
        for u in range(start[i], start[i] + dur[i]):
            slot = events.setdefault(u, {})
            for r, a in reqraw[i]:
                slot[r] = slot.get(r, 0) + a
                if slot[r] > caps[r]:
                    return False
    return True


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get("input", {}) or {}
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    caps = [int(resources[r]) for r in rnames]
    nres = len(rnames)
    ids = [str(j.get("id")) for j in jobs]
    n = len(jobs)
    idx = {}
    for k, jid in enumerate(ids):
        idx[jid] = k

    # validation
    for j in jobs:
        for p in (j.get("after", []) or []):
            if str(p) not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (j.get("id"), p))
        for r, a in (j.get("requires", {}) or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (j.get("id"), r))
            if int(a) > caps[ridx[r]]:
                return _infeasible(state, "job %s requires %s units of %s > capacity %s" % (j.get("id"), a, r, caps[ridx[r]]))

    dur = [max(0, int(j.get("duration", 0))) for j in jobs]
    rel = [max(0, int(j.get("release", 0))) for j in jobs]
    P = [[] for _ in range(n)]
    S = [[] for _ in range(n)]
    for k, j in enumerate(jobs):
        seen = set()
        for p in (j.get("after", []) or []):
            pi = idx[str(p)]
            if pi in seen:
                continue
            seen.add(pi)
            P[k].append(pi)
            S[pi].append(k)
    # cycle detection
    indeg = [len(P[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        i = q.pop()
        topo.append(i)
        for s in S[i]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if indeg[i] > 0][:5]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    reqraw = []
    req = []
    for k, j in enumerate(jobs):
        rr = []
        for r, a in (j.get("requires", {}) or {}).items():
            a = int(a)
            if a > 0:
                rr.append((ridx[r], a))
        reqraw.append(rr)
        if dur[k] > 0:
            req.append([(r, caps[r] - a, a) for (r, a) in rr])
        else:
            req.append([])

    H = max(rel) + sum(dur) + 2
    Hb = sum(dur) + 2
    zeros = [0] * n

    # heads / tails
    head = [0] * n
    for i in topo:
        e = rel[i]
        for p in P[i]:
            e = max(e, head[p] + dur[p])
        head[i] = e
    tail = [0] * n
    for i in reversed(topo):
        t = 0
        for s in S[i]:
            t = max(t, tail[s])
        tail[i] = t + dur[i]
    LB = max(head[i] + tail[i] for i in range(n))
    for r in range(nres):
        work = 0
        mr = None
        for i in range(n):
            for (rr, a) in reqraw[i]:
                if rr == r and dur[i] > 0:
                    work += a * dur[i]
                    mr = rel[i] if mr is None else min(mr, rel[i])
        if caps[r] > 0 and work > 0:
            LB = max(LB, mr + (work + caps[r] - 1) // caps[r])
    nsucc = [0] * n
    for i in range(n):
        seen = set()
        stack = list(S[i])
        while stack:
            x = stack.pop()
            if x in seen:
                continue
            seen.add(x)
            stack.extend(S[x])
        nsucc[i] = len(seen)

    # fallback serial schedule
    fb = [0] * n
    cur = 0
    for i in topo:
        e = max(rel[i], cur)
        for p in P[i]:
            e = max(e, fb[p] + dur[p])
        fb[i] = e
        cur = max(cur, e + dur[i])
    best_start = fb
    best_mk = max(fb[i] + dur[i] for i in range(n))
    best_order = list(topo)

    rng = random.Random(12345)
    deadline = t0 + 1.05

    def rank_of(order):
        rk = [0] * n
        for k, i in enumerate(order):
            rk[i] = k
        return rk

    def evaluate(order):
        rk = rank_of(order)
        st, mk = _sgs(rk, P, S, rel, dur, req, caps, H, n, nres)
        # forward-backward improvement
        for _ in range(4):
            fins = [st[i] + dur[i] for i in range(n)]
            brk = sorted(range(n), key=lambda i: (-fins[i], -st[i]))
            bst, bmk = _sgs(rank_of(brk), S, P, zeros, dur, req, caps, Hb, n, nres)
            ford = sorted(range(n), key=lambda i: (-(bst[i] + dur[i]), -bst[i]))
            st2, mk2 = _sgs(rank_of(ford), P, S, rel, dur, req, caps, H, n, nres)
            if mk2 < mk:
                st, mk = st2, mk2
            else:
                if mk2 == mk:
                    st = st2
                break
        order2 = sorted(range(n), key=lambda i: (st[i], -tail[i]))
        return st, mk, order2

    def consider(st, mk, order):
        nonlocal best_start, best_mk, best_order
        if mk < best_mk:
            best_start, best_mk, best_order = list(st), mk, list(order)

    rules = [
        lambda i: (-tail[i], rel[i]),
        lambda i: (head[i] - (LB - tail[i]), -tail[i]),
        lambda i: (LB - tail[i], head[i]),
        lambda i: (head[i], -tail[i]),
        lambda i: (-nsucc[i], -tail[i]),
        lambda i: (-dur[i] * sum(a for _, a in reqraw[i]), -tail[i]),
        lambda i: (-(tail[i] + head[i]), head[i]),
    ]
    for rf in rules:
        if time.perf_counter() > deadline or best_mk <= LB:
            break
        order = sorted(range(n), key=rf)
        st, mk, o2 = evaluate(order)
        consider(st, mk, o2)

    # biased random sampling
    for _ in range(30):
        if time.perf_counter() > deadline or best_mk <= LB:
            break
        noise = max(1, LB // 4)
        order = sorted(range(n), key=lambda i: -tail[i] + rng.uniform(-noise, noise))
        st, mk, o2 = evaluate(order)
        consider(st, mk, o2)

    # simulated annealing on activity lists
    cur_order = list(best_order)
    cur_mk = best_mk
    temp = 1.0
    it = 0
    since = 0
    while best_mk > LB and n > 1:
        if time.perf_counter() > deadline:
            break
        it += 1
        order = list(cur_order)
        m = rng.random()
        if m < 0.6:
            a = rng.randrange(n)
            x = order.pop(a)
            b = rng.randrange(n)
            order.insert(b, x)
        elif m < 0.85:
            a = rng.randrange(n)
            b = rng.randrange(n)
            order[a], order[b] = order[b], order[a]
        else:
            a = rng.randrange(n)
            b = min(n, a + rng.randint(2, 6))
            seg = order[a:b]
            rng.shuffle(seg)
            order[a:b] = seg
        st, mk, o2 = evaluate(order)
        consider(st, mk, o2)
        d = mk - cur_mk
        if d <= 0 or rng.random() < math.exp(-d / max(temp, 1e-3)):
            cur_order, cur_mk = o2, mk
        if mk < best_mk or d < 0:
            since = 0
        else:
            since += 1
        temp = max(0.2, temp * 0.999)
        if since > 250:
            cur_order, cur_mk = list(best_order), best_mk
            since = 0
            temp = 1.0

    start = [int(x) for x in best_start]
    if not _valid(start, n, P, rel, dur, reqraw, caps):
        start = [int(x) for x in fb]
    state["output"] = {"status": "ok", "start": {ids[i]: start[i] for i in range(n)}}
    return state

import time
import random
import heapq
import math


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t0 = time.perf_counter()
    budget = 1.0
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(res[r]) for r in rnames]
    R = len(rnames)
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, x in enumerate(ids):
        if x not in idx:
            idx[x] = i
    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    preds = []
    req = []
    for i, j in enumerate(jobs):
        ps = []
        seen = set()
        for a in (j.get("after") or []):
            a = str(a)
            if a not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], a))
            k = idx[a]
            if k not in seen:
                seen.add(k)
                ps.append(k)
        preds.append(ps)
        rq = []
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], r))
            u = int(u)
            if u > cap[ridx[r]]:
                return _infeasible(state, "job %s requires %d of %s (capacity %d)" % (ids[i], u, r, cap[ridx[r]]))
            if u > 0:
                rq.append((ridx[r], u))
        req.append(rq)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    # topological order
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    topo = []
    h = 0
    while h < len(dq):
        x = dq[h]; h += 1
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if deg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc[:6]))
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rank = [0] * n
    for k, x in enumerate(topo):
        rank[x] = k
    usesres = [len(req[i]) > 0 and dur[i] > 0 for i in range(n)]

    # bounds
    ES = [0] * n
    for x in topo:
        t = rel[x]
        for p in preds[x]:
            v = ES[p] + dur[p]
            if v > t:
                t = v
        ES[x] = t
    LB = max(ES[i] + dur[i] for i in range(n))
    for r in range(R):
        if cap[r] <= 0:
            continue
        work = 0
        mr = None
        for i in range(n):
            for (rr, u) in req[i]:
                if rr == r and dur[i] > 0:
                    work += u * dur[i]
                    mr = ES[i] if mr is None else min(mr, ES[i])
        if work > 0:
            LB = max(LB, mr + (work + cap[r] - 1) // cap[r])
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dur[x] + m
    nsucc_all = [0] * n
    for x in reversed(topo):
        st = set()
        for s in succs[x]:
            st.add(s)
        nsucc_all[x] = len(st) + sum(len(succs[s]) for s in succs[x])
    H = max(rel) + sum(dur) + max(dur) + 5

    def sgs(order):
        usage = [[0] * H for _ in range(R)]
        start = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                v = start[p] + dur[p]
                if v > t:
                    t = v
            d = dur[j]
            if usesres[j]:
                rq = req[j]
                while True:
                    ok = True
                    for (r, u) in rq:
                        row = usage[r]
                        lim = cap[r] - u
                        for tt in range(t, t + d):
                            if row[tt] > lim:
                                ok = False
                                t = tt + 1
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    row = usage[r]
                    for tt in range(t, t + d):
                        row[tt] += u
            start[j] = t
        ms = 0
        for j in range(n):
            v = start[j] + dur[j]
            if v > ms:
                ms = v
        return start, ms

    def backward(start, M):
        order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -rank[j]))
        usage = [[0] * (M + 2) for _ in range(R)]
        ns = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if ns[s] < lf:
                    lf = ns[s]
            d = dur[j]
            t = lf - d
            if usesres[j]:
                rq = req[j]
                while True:
                    if t < start[j]:
                        return None
                    ok = True
                    for (r, u) in rq:
                        row = usage[r]
                        lim = cap[r] - u
                        for tt in range(t + d - 1, t - 1, -1):
                            if row[tt] > lim:
                                ok = False
                                t = tt - d
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    row = usage[r]
                    for tt in range(t, t + d):
                        row[tt] += u
            if t < start[j]:
                return None
            ns[j] = t
        return ns

    def fbi(start, ms):
        while True:
            ns = backward(start, ms)
            if ns is None:
                return start, ms
            order = sorted(range(n), key=lambda j: (ns[j], rank[j]))
            s2, m2 = sgs(order)
            if m2 < ms:
                start, ms = s2, m2
            else:
                if m2 == ms:
                    start = s2
                return start, ms

    def gen(key):
        dg = indeg[:]
        hp = [(key[i], rank[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, _, x = heapq.heappop(hp)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(hp, (key[s], rank[s], s))
        return out

    def valid(start):
        for i in range(n):
            if start[i] < rel[i]:
                return False
            for p in preds[i]:
                if start[i] < start[p] + dur[p]:
                    return False
        ev = {}
        for i in range(n):
            if usesres[i]:
                for tt in range(start[i], start[i] + dur[i]):
                    row = ev.get(tt)
                    if row is None:
                        row = [0] * R
                        ev[tt] = row
                    for (r, u) in req[i]:
                        row[r] += u
        for row in ev.values():
            for r in range(R):
                if row[r] > cap[r]:
                    return False
        return True

    best = {"start": None, "ms": None, "order": None}

    def consider(order):
        s, m = sgs(order)
        if best["ms"] is None or m <= best["ms"] + 2:
            s, m = fbi(s, m)
        if best["ms"] is None or m < best["ms"] or (m == best["ms"] and random.random() < 0.3):
            best["start"] = s
            best["ms"] = m
            best["order"] = sorted(range(n), key=lambda j: (s[j], rank[j]))
        return m, s

    work = [sum(u for (_, u) in req[i]) * dur[i] for i in range(n)]
    rules = [
        [-tail[i] for i in range(n)],
        [ES[i] - (tail[i]) for i in range(n)],
        [ES[i] for i in range(n)],
        [-nsucc_all[i] for i in range(n)],
        [-(work[i] + sum(work[s] for s in succs[i])) for i in range(n)],
        [rel[i] - tail[i] for i in range(n)],
        [-dur[i] for i in range(n)],
        [rank[i] for i in range(n)],
    ]
    base_order = topo[:]
    for key in rules:
        consider(gen(key))
        if best["ms"] <= LB:
            break

    rng = random.Random(12345)
    cur_order = best["order"][:]
    cur_ms = best["ms"]
    it = 0
    stall = 0
    while best["ms"] > LB and time.perf_counter() - t0 < budget:
        it += 1
        if stall > 60 or it % 7 == 0:
            base = rules[rng.randrange(len(rules))]
            sc = max(1.0, max(abs(v) for v in base))
            key = [base[i] + rng.uniform(-0.6, 0.6) * sc * rng.random() for i in range(n)]
            o = gen(key)
            m, s = consider(o)
            if stall > 60:
                cur_order = sorted(range(n), key=lambda j: (s[j], rank[j]))
                cur_ms = m
                stall = 0
            continue
        o = cur_order[:]
        moves = 1 + rng.randrange(3)
        for _ in range(moves):
            p = rng.randrange(n)
            x = o.pop(p)
            pos = {o[k]: k for k in range(len(o))}
            lo = 0
            for q in preds[x]:
                if pos[q] + 1 > lo:
                    lo = pos[q] + 1
            hi = len(o)
            for q in succs[x]:
                if pos[q] < hi:
                    hi = pos[q]
            o.insert(rng.randint(lo, hi), x)
        m, s = consider(o)
        if m <= cur_ms:
            if m < cur_ms:
                stall = 0
            else:
                stall += 1
            cur_ms = m
            cur_order = sorted(range(n), key=lambda j: (s[j], rank[j]))
        else:
            stall += 1

    start = best["start"]
    if start is None or not valid(start):
        start, _ = sgs(base_order)
    state["output"] = {"status": "ok", "start": {ids[i]: int(start[i]) for i in range(n)}}
    return state

import time
import random
import heapq


def _validate(inp):
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = {}
    for i, jb in enumerate(jobs):
        ids.setdefault(str(jb.get("id")), i)
    for jb in jobs:
        for p in (jb.get("after") or []):
            if str(p) not in ids:
                return "job %s references unknown job %s" % (jb.get("id"), p)
        for r, u in (jb.get("requires") or {}).items():
            if r not in resources:
                return "job %s references unknown resource %s" % (jb.get("id"), r)
            if int(u) > int(resources[r]):
                return "job %s requires %s units of %s > capacity %s" % (jb.get("id"), u, r, resources[r])
    n = len(jobs)
    indeg = [0] * n
    succ = [[] for _ in range(n)]
    for j, jb in enumerate(jobs):
        for p in (jb.get("after") or []):
            pi = ids[str(p)]
            succ[pi].append(j)
            indeg[j] += 1
    st = [j for j in range(n) if indeg[j] == 0]
    cnt = 0
    while st:
        x = st.pop()
        cnt += 1
        for y in succ[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                st.append(y)
    if cnt < n:
        cyc = [str(jobs[j].get("id")) for j in range(n) if indeg[j] > 0][:6]
        return "precedence cycle among " + ", ".join(cyc)
    return None


def validate_node(state, params):
    inp = state.get("input") or {}
    try:
        reason = _validate(inp)
    except Exception as e:
        reason = "malformed input: " + str(e)[:80]
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        state["is_infeasible"] = True
    else:
        state["is_infeasible"] = False
    return state


def solve_node(state, params):
    if state.get("is_infeasible"):
        return state
    T0 = time.perf_counter()
    BUDGET = 1.1
    inp = state["input"]
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    R = len(cap)
    ids = {}
    for i, jb in enumerate(jobs):
        ids.setdefault(str(jb.get("id")), i)
    dur = [max(0, int(jb.get("duration", 0) or 0)) for jb in jobs]
    rel = [max(0, int(jb.get("release", 0) or 0)) for jb in jobs]
    preds = [sorted(set(ids[str(p)] for p in (jb.get("after") or []))) for jb in jobs]
    succs = [[] for _ in range(n)]
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
    req = []
    for j, jb in enumerate(jobs):
        lst = []
        if dur[j] > 0:
            for r, u in (jb.get("requires") or {}).items():
                u = int(u)
                if u > 0:
                    lst.append((ridx[r], u))
        req.append(lst)

    # topological order (FIFO Kahn)
    indeg = [len(preds[j]) for j in range(n)]
    topo = [j for j in range(n) if indeg[j] == 0]
    h = 0
    while h < len(topo):
        x = topo[h]
        h += 1
        for y in succs[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                topo.append(y)
    tpos = [0] * n
    for i, j in enumerate(topo):
        tpos[j] = i
    H = max(rel) + sum(dur) + max(dur) + 3

    # heads, tails, bounds
    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            f = es[p] + dur[p]
            if f > t:
                t = f
        es[j] = t
    cpm = max(es[j] + dur[j] for j in range(n))
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = m + dur[j]
    lb = cpm
    for r in range(R):
        if cap[r] <= 0:
            continue
        items = []
        for j in range(n):
            for (rr, u) in req[j]:
                if rr == r:
                    items.append((es[j], u * dur[j]))
        if not items:
            continue
        items.sort()
        suffix = 0
        for k in range(len(items) - 1, -1, -1):
            suffix += items[k][1]
            T = items[k][0]
            v = T + (suffix + cap[r] - 1) // cap[r]
            if v > lb:
                lb = v
    desc = [set() for _ in range(n)]
    nsucc_all = [0] * n
    for j in reversed(topo):
        for s in succs[j]:
            desc[j].add(s)
            desc[j] |= desc[s]
        nsucc_all[j] = len(desc[j])
    work = [sum(u * dur[j] / float(cap[r]) for (r, u) in req[j]) for j in range(n)]

    def sgs(order):
        usage = [[0] * H for _ in range(R)]
        start = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = start[p] + dur[p]
                if f > t:
                    t = f
            rq = req[j]
            if rq:
                d = dur[j]
                while True:
                    bad = -1
                    for (r, u) in rq:
                        row = usage[r]
                        lim = cap[r] - u
                        tt = t + d - 1
                        while tt >= t and tt > bad:
                            if row[tt] > lim:
                                bad = tt
                                break
                            tt -= 1
                    if bad < 0:
                        break
                    t = bad + 1
                for (r, u) in rq:
                    row = usage[r]
                    for tt in range(t, t + d):
                        row[tt] += u
            start[j] = t
        return start

    def mk(start):
        m = 0
        for j in range(n):
            v = start[j] + dur[j]
            if v > m:
                m = v
        return m

    def backward(start, M):
        order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -tpos[j]))
        usage = [[0] * (M + 1) for _ in range(R)]
        ns = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if ns[s] < lf:
                    lf = ns[s]
            d = dur[j]
            t = lf - d
            rq = req[j]
            if rq:
                while True:
                    if t < rel[j]:
                        return None
                    bad = -1
                    for (r, u) in rq:
                        row = usage[r]
                        lim = cap[r] - u
                        tt = t
                        end = t + d
                        while tt < end and (bad < 0 or tt < bad):
                            if row[tt] > lim:
                                bad = tt
                                break
                            tt += 1
                    if bad < 0:
                        break
                    t = bad - d
                for (r, u) in rq:
                    row = usage[r]
                    for tt in range(t, t + d):
                        row[tt] += u
            if t < rel[j]:
                return None
            ns[j] = t
        return ns

    def evaluate(order):
        s = sgs(order)
        m = mk(s)
        crit = None
        for _ in range(8):
            b = backward(s, m)
            if b is None:
                crit = None
                break
            crit = b
            o2 = sorted(range(n), key=lambda j: (b[j], tpos[j]))
            s2 = sgs(o2)
            m2 = mk(s2)
            if m2 < m:
                s, m = s2, m2
                crit = None
                continue
            break
        return m, s, crit

    def keys_to_order(key):
        deg = [len(preds[j]) for j in range(n)]
        hp = [(key[j], tpos[j], j) for j in range(n) if deg[j] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, _, x = heapq.heappop(hp)
            out.append(x)
            for y in succs[x]:
                deg[y] -= 1
                if deg[y] == 0:
                    heapq.heappush(hp, (key[y], tpos[y], y))
        return out

    rnd = random.Random(20251123)
    best = {"m": None, "s": None}
    pool = []
    seen = set()

    def consider(key):
        m, s, b = evaluate(keys_to_order(key))
        imp = False
        if best["m"] is None or m < best["m"]:
            best["m"] = m
            best["s"] = s
            imp = True
        sig = tuple(s)
        if sig not in seen:
            seen.add(sig)
            if b is not None:
                crit = [j for j in range(n) if dur[j] > 0 and b[j] == s[j]]
            else:
                crit = []
            if not crit:
                crit = [j for j in range(n) if s[j] + dur[j] == m]
            pool.append([m, rnd.random(), [s[j] + 0.001 * tpos[j] for j in range(n)], crit])
        return imp

    L = cpm + 1
    rules = [
        [L - tail[j] for j in range(n)],
        [L - tail[j] + dur[j] for j in range(n)],
        [es[j] for j in range(n)],
        [es[j] - tail[j] for j in range(n)],
        [-nsucc_all[j] for j in range(n)],
        [-(tail[j] + work[j]) for j in range(n)],
        [-work[j] for j in range(n)],
        [-dur[j] for j in range(n)],
        [rel[j] - tail[j] * 0.5 for j in range(n)],
        [rel[j] - tail[j] for j in range(n)],
        [float(tpos[j]) for j in range(n)],
    ]
    for k in rules:
        consider(k)
        if best["m"] <= lb:
            break

    POP = 20
    it = 0
    last_imp = 0
    sortkey = lambda e: (e[0], e[1])
    while best["m"] > lb and time.perf_counter() - T0 < BUDGET:
        it += 1
        if len(pool) > POP:
            pool.sort(key=sortkey)
            del pool[POP:]
        if it - last_imp > 350 and len(pool) > 3:
            pool.sort(key=sortkey)
            del pool[3:]
            last_imp = it
        if it % 6 == 0 or len(pool) < 2:
            base = rules[rnd.randrange(len(rules))]
            sc = max(1.0, max(abs(x) for x in base))
            sig = rnd.choice([0.1, 0.3, 0.6])
            key = [base[j] + rnd.gauss(0, sig * sc) for j in range(n)]
        else:
            pool.sort(key=sortkey)
            pa = pool[min(int(rnd.random() ** 2 * len(pool)), len(pool) - 1)]
            a = pa[2]
            crit = pa[3]
            if rnd.random() < 0.4 and len(pool) > 1:
                bk = pool[rnd.randrange(len(pool))][2]
                key = [a[j] if rnd.random() < 0.5 else bk[j] for j in range(n)]
            else:
                key = list(a)
            nm = 1 + (rnd.random() < 0.35)
            for _ in range(nm):
                mode = rnd.random()
                if mode < 0.2:
                    sg = rnd.choice([0.5, 1.5, 3.0])
                    for j in range(n):
                        if rnd.random() < 0.3:
                            key[j] += rnd.gauss(0, sg)
                elif mode < 0.35:
                    i = rnd.randrange(n)
                    k = rnd.randrange(n)
                    key[i], key[k] = key[k], key[i]
                elif mode < 0.6 and crit:
                    # move a critical job earlier, before some job with smaller key
                    i = crit[rnd.randrange(len(crit))]
                    cands = [k for k in range(n) if key[k] < key[i]]
                    if cands:
                        k = cands[rnd.randrange(len(cands))]
                        key[i] = key[k] - 0.0005
                    else:
                        key[i] -= rnd.uniform(0.5, 8)
                elif mode < 0.8:
                    # precedence-window insertion
                    i = rnd.randrange(n)
                    lo = min(key) - 1.0
                    for p in preds[i]:
                        if key[p] > lo:
                            lo = key[p]
                    hi = max(key) + 1.0
                    for s in succs[i]:
                        if key[s] < hi:
                            hi = key[s]
                    if hi < lo:
                        hi = lo
                    key[i] = rnd.uniform(lo, hi)
                else:
                    i = rnd.randrange(n)
                    if rnd.random() < 0.6:
                        key[i] -= rnd.uniform(0.5, 8)
                    else:
                        key[i] += rnd.uniform(0.5, 8)
        if consider(key):
            last_imp = it

    def valid(start):
        for i in range(n):
            if start[i] < rel[i]:
                return False
            for p in preds[i]:
                if start[i] < start[p] + dur[p]:
                    return False
        ev = {}
        for i in range(n):
            if req[i]:
                for tt in range(start[i], start[i] + dur[i]):
                    row = ev.get(tt)
                    if row is None:
                        row = [0] * R
                        ev[tt] = row
                    for (r, u) in req[i]:
                        row[r] += u
        for row in ev.values():
            for r in range(R):
                if row[r] > cap[r]:
                    return False
        return True

    s = best["s"]
    if s is None or not valid(s):
        s = sgs(topo)
    state["output"] = {"status": "ok",
                       "start": {str(jobs[j].get("id")): int(s[j]) for j in range(n)}}
    return state

import time
import random
import heapq
import math


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t0 = time.perf_counter()
    BUDGET = 1.15
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(res[r]) for r in rnames]
    R = len(rnames)
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, x in enumerate(ids):
        if x not in idx:
            idx[x] = i
    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    preds = []
    req = []
    for i, j in enumerate(jobs):
        ps = []
        seen = set()
        for a in (j.get("after") or []):
            a = str(a)
            if a not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], a))
            k = idx[a]
            if k not in seen:
                seen.add(k)
                ps.append(k)
        preds.append(ps)
        rq = []
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], r))
            u = int(u)
            if u > cap[ridx[r]]:
                return _infeasible(state, "job %s requires %d of %s (capacity %d)" % (ids[i], u, r, cap[ridx[r]]))
            if u > 0:
                rq.append((ridx[r], u))
        req.append(rq)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    topo = []
    h = 0
    while h < len(dq):
        x = dq[h]
        h += 1
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if deg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc[:6]))
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for k, x in enumerate(topo):
        rank[x] = k
    usesres = [len(req[i]) > 0 and dur[i] > 0 for i in range(n)]

    # ---- heads, tails, lower bound ----
    ES = [0] * n
    for x in topo:
        t = rel[x]
        for p in preds[x]:
            v = ES[p] + dur[p]
            if v > t:
                t = v
        ES[x] = t
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dur[x] + m
    LB = max(ES[i] + dur[i] for i in range(n))
    for r in range(R):
        if cap[r] <= 0:
            continue
        items = []
        for i in range(n):
            if usesres[i]:
                for (rr, u) in req[i]:
                    if rr == r:
                        items.append((ES[i], u * dur[i]))
        if not items:
            continue
        items.sort()
        suf = 0
        for k in range(len(items) - 1, -1, -1):
            suf += items[k][1]
            if k == 0 or items[k - 1][0] != items[k][0]:
                v = items[k][0] + (suf + cap[r] - 1) // cap[r]
                if v > LB:
                    LB = v
    desc = [set() for _ in range(n)]
    for x in reversed(topo):
        for s in succs[x]:
            desc[x].add(s)
            desc[x] |= desc[s]
    nsucc_all = [len(desc[i]) for i in range(n)]
    workr = [sum(u * dur[i] / max(1, cap[r]) for (r, u) in req[i]) for i in range(n)]
    H = max(rel) + sum(dur) + max(dur) + 5

    # ---- decoders ----
    def sgs(order):
        usage = [[0] * H for _ in range(R)]
        start = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                v = start[p] + dur[p]
                if v > t:
                    t = v
            d = dur[j]
            if usesres[j]:
                rq = req[j]
                while True:
                    ok = True
                    for (r, u) in rq:
                        row = usage[r]
                        lim = cap[r] - u
                        for tt in range(t + d - 1, t - 1, -1):
                            if row[tt] > lim:
                                ok = False
                                t = tt + 1
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    row = usage[r]
                    for tt in range(t, t + d):
                        row[tt] += u
            start[j] = t
        ms = 0
        for j in range(n):
            v = start[j] + dur[j]
            if v > ms:
                ms = v
        return start, ms

    def backward(start, M):
        order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -rank[j]))
        usage = [[0] * (M + 2) for _ in range(R)]
        ns = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if ns[s] < lf:
                    lf = ns[s]
            d = dur[j]
            t = lf - d
            if usesres[j]:
                rq = req[j]
                while True:
                    if t < rel[j]:
                        return None
                    ok = True
                    for (r, u) in rq:
                        row = usage[r]
                        lim = cap[r] - u
                        for tt in range(t, t + d):
                            if row[tt] > lim:
                                ok = False
                                t = tt - d
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    row = usage[r]
                    for tt in range(t, t + d):
                        row[tt] += u
            if t < rel[j]:
                return None
            ns[j] = t
        return ns

    def fbi(start, ms):
        for _ in range(6):
            ns = backward(start, ms)
            if ns is None:
                return start, ms
            order = sorted(range(n), key=lambda j: (ns[j], rank[j]))
            s2, m2 = sgs(order)
            if m2 < ms:
                start, ms = s2, m2
            else:
                if m2 == ms:
                    start = s2
                return start, ms
        return start, ms

    def gen(key):
        dg = indeg[:]
        hp = [(key[i], rank[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, _, x = heapq.heappop(hp)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(hp, (key[s], rank[s], s))
        return out

    def valid(start):
        for i in range(n):
            if start[i] < rel[i]:
                return False
            for p in preds[i]:
                if start[i] < start[p] + dur[p]:
                    return False
        ev = {}
        for i in range(n):
            if usesres[i]:
                for tt in range(start[i], start[i] + dur[i]):
                    row = ev.get(tt)
                    if row is None:
                        row = [0] * R
                        ev[tt] = row
                    for (r, u) in req[i]:
                        row[r] += u
        for row in ev.values():
            for r in range(R):
                if row[r] > cap[r]:
                    return False
        return True

    rng = random.Random(20251123)
    best = {"start": None, "ms": None}
    POP = 14
    pool = []          # entries: [ms, rand, order(list), start(list)]
    seen = set()

    def evaluate(order):
        s, m = sgs(order)
        s, m = fbi(s, m)
        if best["ms"] is None or m < best["ms"]:
            best["ms"] = m
            best["start"] = s
        o = sorted(range(n), key=lambda j: (s[j], rank[j]))
        sig = tuple(s)
        if sig not in seen:
            seen.add(sig)
            pool.append([m, rng.random(), o, s])
        return m

    def trim():
        pool.sort(key=lambda e: (e[0], e[1]))
        del pool[POP:]

    rules = [
        [-tail[i] for i in range(n)],
        [ES[i] - tail[i] for i in range(n)],
        [ES[i] for i in range(n)],
        [-nsucc_all[i] for i in range(n)],
        [-(tail[i] + workr[i]) for i in range(n)],
        [-workr[i] for i in range(n)],
        [rel[i] - tail[i] for i in range(n)],
        [rel[i] - 0.5 * tail[i] for i in range(n)],
        [-dur[i] for i in range(n)],
        [rank[i] for i in range(n)],
    ]
    for key in rules:
        evaluate(gen(key))
        if best["ms"] <= LB:
            break
    trim()

    def rule_sample():
        base = rules[rng.randrange(len(rules))]
        sc = max(1.0, max(abs(v) for v in base))
        sg = rng.choice([0.1, 0.3, 0.6])
        return gen([base[i] + rng.gauss(0, sg * sc) for i in range(n)])

    def pick():
        k = min(int(rng.random() ** 2 * len(pool)), len(pool) - 1)
        return pool[k]

    def insertion(o, moves):
        o = o[:]
        for _ in range(moves):
            p = rng.randrange(n)
            x = o.pop(p)
            pos = {o[k]: k for k in range(len(o))}
            lo = 0
            for q in preds[x]:
                if pos[q] + 1 > lo:
                    lo = pos[q] + 1
            hi = len(o)
            for q in succs[x]:
                if pos[q] < hi:
                    hi = pos[q]
            o.insert(rng.randint(lo, hi), x)
        return o

    def critical_jobs(s, m):
        crit = set()
        stack = [j for j in range(n) if s[j] + dur[j] == m]
        while stack:
            j = stack.pop()
            if j in crit:
                continue
            crit.add(j)
            for p in preds[j]:
                if s[p] + dur[p] == s[j]:
                    stack.append(p)
        # also jobs finishing right where a critical job starts (resource-linked)
        starts = set(s[j] for j in crit)
        for j in range(n):
            if j not in crit and dur[j] > 0 and (s[j] + dur[j]) in starts and rng.random() < 0.5:
                crit.add(j)
        return list(crit)

    it = 0
    stall = 0
    last_best = best["ms"]
    while best["ms"] > LB and time.perf_counter() - t0 < BUDGET:
        it += 1
        op = rng.random()
        if len(pool) < 2 or op < 0.12:
            o = rule_sample()
        elif op < 0.45:
            e = pick()
            o = insertion(e[2], 1 + rng.randrange(3))
        elif op < 0.65:
            a = pick()
            b = pool[rng.randrange(len(pool))]
            pa = {j: k for k, j in enumerate(a[2])}
            pb = {j: k for k, j in enumerate(b[2])}
            key = [pa[j] if rng.random() < 0.5 else pb[j] for j in range(n)]
            if rng.random() < 0.5:
                i = rng.randrange(n)
                key[i] -= rng.uniform(0.5, 6)
            o = gen(key)
        elif op < 0.82:
            e = pick()
            s = e[3]
            key = [s[j] + 0.001 * rank[j] for j in range(n)]
            mode = rng.random()
            if mode < 0.5:
                sg = rng.choice([0.5, 1.5, 3.0])
                for j in range(n):
                    if rng.random() < 0.3:
                        key[j] += rng.gauss(0, sg)
            else:
                i = rng.randrange(n)
                k = rng.randrange(n)
                key[i], key[k] = key[k], key[i]
            o = gen(key)
        else:
            e = pick()
            s = e[3]
            cj = critical_jobs(s, e[0])
            key = [s[j] + 0.001 * rank[j] for j in range(n)]
            for _ in range(1 + rng.randrange(2)):
                j = cj[rng.randrange(len(cj))] if cj else rng.randrange(n)
                key[j] -= rng.uniform(1, max(2.0, dur[j] + 4))
            o = gen(key)
        evaluate(o)
        if len(pool) > 3 * POP:
            trim()
        if it % 8 == 0:
            trim()
        if best["ms"] < last_best:
            last_best = best["ms"]
            stall = 0
        else:
            stall += 1
        if stall > 250:
            trim()
            del pool[max(2, POP // 3):]
            for _ in range(4):
                evaluate(rule_sample())
            stall = 0

    start = best["start"]
    if start is None or not valid(start):
        start, _ = sgs(topo)
    state["output"] = {"status": "ok", "start": {ids[i]: int(start[i]) for i in range(n)}}
    return state

