                break
            if u > res[r]:
                reason = "job %s requires %s units of %s, capacity %s" % (j.get("id"), u, r, res[r])
                break
        if reason:
            break
    if reason is None:
        idx = {x: i for i, x in enumerate(ids)}
        n = len(jobs)
        indeg = [0] * n
        succ = [[] for _ in range(n)]
        for i, j in enumerate(jobs):
            for p in set(str(q) for q in (j.get("after") or [])):
                succ[idx[p]].append(i)
                indeg[i] += 1
        q = [i for i in range(n) if indeg[i] == 0]
        seen = 0
        while q:
            v = q.pop()
            seen += 1
            for s in succ[v]:
                indeg[s] -= 1
                if indeg[s] == 0:
                    q.append(s)
        if seen < n:
            cyc = [ids[i] for i in range(n) if indeg[i] > 0][:6]
            reason = "precedence cycle among " + ", ".join(cyc)
    if reason is not None:
        state["feasible"] = False
        state["output"] = {"status": "infeasible", "reason": reason}
    else:
        state["feasible"] = True
