            s = start.get(i)
            if not isinstance(s, int) or s < int(j.get("release", 0)):
                return False
            for p in (j.get("after") or []):
                if s < start[str(p)] + int(byid[str(p)]["duration"]):
                    return False
            d = int(j["duration"])
            if d > 0:
                for r, u in (j.get("requires") or {}).items():
                    if u > 0:
                        for t in range(s, s + d):
                            k = (r, t)
                            ev[k] = ev.get(k, 0) + u
                            if ev[k] > res[r]:
                                return False
        return True
    except Exception:
        return False


def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 1.2
    inp = state["input"]
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(res[r]) for r in rnames]
    R = len(cap)
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    idx = {x: i for i, x in enumerate(ids)}
    dur = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0)) for j in jobs]
    preds = [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
    dem = [[] for _ in range(n)]
    dm = [[0] * R for _ in range(n)]
    for j in range(n):
        if dur[j] > 0:
            for r, u in (jobs[j].get("requires") or {}).items():
                u = int(u)
                if u > 0:
                    dem[j].append((ridx[r], u))
                    dm[j][ridx[r]] += u

    # topological order
    indeg = [len(preds[j]) for j in range(n)]
    q = [j for j in range(n) if indeg[j] == 0]
    topo = []
    while q:
        v = q.pop()
        topo.append(v)
        for s in succs[v]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)

    est0 = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            t = max(t, est0[p] + dur[p])
        est0[j] = t
    tail = [0] * n
    for j in reversed(topo):
        t = 0
        for s in succs[j]:
            t = max(t, tail[s])
        tail[j] = t + dur[j]

    LB0 = 0
    for j in range(n):
        LB0 = max(LB0, est0[j] + tail[j])
    for r in range(R):
        items = sorted((est0[j], dm[j][r] * dur[j]) for j in range(n) if dm[j][r] > 0)
        if not items or cap[r] <= 0:
            continue
        E = 0
        for k in range(len(items) - 1, -1, -1):
            E += items[k][1]
            LB0 = max(LB0, items[k][0] + (E + cap[r] - 1) // cap[r])

    H = (max(rel) if rel else 0) + sum(dur) + 2
    L = H + 16

    def earliest(usage, j, t):
        d = dur[j]
        if d == 0 or not dem[j]:
            return t
        while True:
            ok = True
            for r, u in dem[j]:
                lim = cap[r] - u
                ur = usage[r]
                for tt in range(t + d - 1, t - 1, -1):
                    if ur[tt] > lim:
                        t = tt + 1
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return t

    def sgs(prio):
        usage = [[0] * L for _ in range(R)]
        npred = [len(preds[j]) for j in range(n)]
        ready = rel[:]
        heap = [(prio[j], j) for j in range(n) if npred[j] == 0]
        heapq.heapify(heap)
        st = [0] * n
        mk = 0
        while heap:
            _, j = heapq.heappop(heap)
            t = earliest(usage, j, ready[j])
            st[j] = t
            e = t + dur[j]
            for r, u in dem[j]:
                ur = usage[r]
                for tt in range(t, e):
                    ur[tt] += u
            if e > mk:
                mk = e
            for s in succs[j]:
                if e > ready[s]:
                    ready[s] = e
                npred[s] -= 1
                if npred[s] == 0:
                    heapq.heappush(heap, (prio[s], s))
        return mk, st

    # sequential fallback (always valid)
    seq = [0] * n
    tcur = 0
    for j in topo:
        t = max(tcur, rel[j])
        for p in preds[j]:
            t = max(t, seq[p] + dur[p])
        seq[j] = t
        tcur = t + dur[j]
    best_mk = max([seq[j] + dur[j] for j in range(n)] + [0])
    best_st = seq[:]

    energy = [sum(dm[j]) * dur[j] for j in range(n)]
    rules = [
        [(-tail[j], est0[j]) for j in range(n)],
        [(est0[j] - (LB0 - tail[j]), j) for j in range(n)],
        [(est0[j], -tail[j]) for j in range(n)],
        [(-(tail[j] + len(succs[j])), j) for j in range(n)],
        [(-tail[j] - 0.1 * energy[j], j) for j in range(n)],
    ]
    for pr in rules:
        mk, st = sgs(pr)
        if mk < best_mk:
            best_mk, best_st = mk, st
    rng = random.Random(12345)
    while time.perf_counter() - T0 < 0.15 and best_mk > LB0:
        pr = [(-tail[j] * (1.0 + 0.6 * rng.random()), j) for j in range(n)]
        mk, st = sgs(pr)
        if mk < best_mk:
            best_mk, best_st = mk, st

    # ---------- Schedule-or-Postpone branch and bound with LDS ----------
    best = [best_mk, best_st[:]]
    st = [-1] * n
    usage = [[0] * L for _ in range(R)]
    nodes = [0]
    stop = [False]
    cut = [False]

    def place(j, t, sign):
        e = t + dur[j]
        for r, u in dem[j]:
            ur = usage[r]
            v = sign * u
            for tt in range(t, e):
                ur[tt] += v

    def dfs(post, curmk, nfix, disc):
        if stop[0]:
            return
        nodes[0] += 1
        if (nodes[0] & 63) == 0 and time.perf_counter() - T0 > BUDGET:
            stop[0] = True
            return
        if nfix == n:
            if curmk < best[0]:
                best[0] = curmk
                best[1] = st[:]
            return
        UB = best[0]
        if curmk >= UB:
            return
        ls = [0] * n
        elig = []
        lb = curmk
        for j in topo:
            if st[j] >= 0:
                continue
            t = rel[j]
            el = True
            for p in preds[j]:
                if st[p] >= 0:
                    v = st[p] + dur[p]
                else:
                    v = ls[p] + dur[p]
                    el = False
                if v > t:
                    t = v
            if el:
                t = earliest(usage, j, t)
                elig.append(j)
            ls[j] = t
            v = t + tail[j]
            if v > lb:
                lb = v
                if lb >= UB:
                    return
        # energy test: all unfixed must finish by UB-1
        T = UB - 1
        for r in range(R):
            E = 0
            t0 = None
            for j in range(n):
                if st[j] < 0 and dm[j][r] > 0:
                    E += dm[j][r] * dur[j]
                    if t0 is None or ls[j] < t0:
                        t0 = ls[j]
            if E == 0:
                continue
            if T <= t0:
                return
            avail = cap[r] * (T - t0)
            for f in range(n):
                if st[f] >= 0 and dm[f][r] > 0:
                    a = max(st[f], t0)
                    b = min(st[f] + dur[f], T)
                    if b > a:
                        avail -= dm[f][r] * (b - a)
            if E > avail:
                return
        # resource-free jobs: start at earliest (dominant)
        for j in elig:
            if not dem[j]:
                t = ls[j]
                st[j] = t
                dfs(post, max(curmk, t + dur[j]), nfix + 1, disc)
                st[j] = -1
                return
        newpost = {}
        sel = []
        for j in elig:
            if j in post:
                if ls[j] > post[j]:
                    sel.append(j)
                else:
                    newpost[j] = post[j]
            else:
                sel.append(j)
        if not sel:
            return
        j = min(sel, key=lambda x: (ls[x], -tail[x], x))
        e = ls[j]
        for k in newpost:
            if newpost[k] < e:
                return
        st[j] = e
        place(j, e, 1)
        dfs(newpost, max(curmk, e + dur[j]), nfix + 1, disc)
        place(j, e, -1)
        st[j] = -1
        if stop[0]:
            return
        if disc > 0:
            np2 = dict(newpost)
            np2[j] = e
            dfs(np2, curmk, nfix, disc - 1)
        else:
            cut[0] = True

    k = 0
    while not stop[0] and best[0] > LB0 and k <= 2 * n + 2:
        if time.perf_counter() - T0 > BUDGET:
            break
        cut[0] = False
        try:
            dfs({}, 0, 0, k)
        except RecursionError:
            break
        if stop[0] or best[0] <= LB0:
            break
        if not cut[0]:
            break  # exhaustive: optimality proven
        k += 1

    cand = [best[1], best_st, seq]
    for c in cand:
        sd = {ids[j]: int(c[j]) for j in range(n)}
        if _check(jobs, res, sd):
            state["output"] = {"status": "ok", "start": sd}
            return state
    state["output"] = {"status": "ok", "start": {ids[j]: int(seq[j]) for j in range(n)}}
    return state

