        LB0 = max(LB0, est0[j] + tail[j])
    for r in range(R):
        items = sorted((est0[j], dm[j][r] * dur[j]) for j in range(n) if dm[j][r] > 0)
        if not items or cap[r] <= 0:
            continue
        E = 0
        for k in range(len(items) - 1, -1, -1):
            E += items[k][1]
            LB0 = max(LB0, items[k][0] + (E + cap[r] - 1) // cap[r])

    H = (max(rel) if rel else 0) + sum(dur) + 2
    L = H + 16

    def earliest(usage, j, t):
        d = dur[j]
        if d == 0 or not dem[j]:
            return t
        while True:
            ok = True
            for r, u in dem[j]:
                lim = cap[r] - u
                ur = usage[r]
                for tt in range(t + d - 1, t - 1, -1):
                    if ur[tt] > lim:
                        t = tt + 1
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return t

    def latest(usage, j, lo, hi):
        d = dur[j]
        if d == 0 or not dem[j]:
            return hi
        t = hi
        while True:
            if t <= lo:
                return lo
            ok = True
            for r, u in dem[j]:
                lim = cap[r] - u
                ur = usage[r]
                for tt in range(t, t + d):
                    if ur[tt] > lim:
                        t = tt - d
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return t

    def put(usage, j, t, sign):
        e = t + dur[j]
        for r, u in dem[j]:
            ur = usage[r]
            v = sign * u
            for tt in range(t, e):
                ur[tt] += v

    def evaluate(lst):
        usage = [[0] * L for _ in range(R)]
        st = [0] * n
        for j in lst:
            t = rel[j]
            for p in preds[j]:
                v = st[p] + dur[p]
                if v > t:
                    t = v
            t = earliest(usage, j, t)
            st[j] = t
            put(usage, j, t, 1)
        mk = 0
        for j in range(n):
            if st[j] + dur[j] > mk:
                mk = st[j] + dur[j]
        for _it in range(4):
            # right justification
            order = sorted(range(n), key=lambda j: (-(st[j] + dur[j]), -tpos[j]))
            for j in order:
                lim = mk
                for s in succs[j]:
                    if st[s] < lim:
                        lim = st[s]
                hi = lim - dur[j]
                if hi > st[j]:
                    if dem[j]:
                        put(usage, j, st[j], -1)
                        t = latest(usage, j, st[j], hi)
                        put(usage, j, t, 1)
                    else:
                        t = hi
                    st[j] = t
            # left justification
            order = sorted(range(n), key=lambda j: (st[j], tpos[j]))
            for j in order:
                t = rel[j]
                for p in preds[j]:
                    v = st[p] + dur[p]
                    if v > t:
                        t = v
                if t < st[j]:
                    if dem[j]:
                        put(usage, j, st[j], -1)
                        t = earliest(usage, j, t)
                        if t > st[j]:
                            t = st[j]
                        put(usage, j, t, 1)
                    st[j] = t
            mk2 = 0
            for j in range(n):
                if st[j] + dur[j] > mk2:
                    mk2 = st[j] + dur[j]
            if mk2 >= mk:
                mk = mk2
                break
            mk = mk2
        nl = sorted(range(n), key=lambda j: (st[j], tpos[j]))
        return mk, st, nl

    def list_from_prio(prio):
        npred = [len(preds[j]) for j in range(n)]
        heap = [(prio[j], j) for j in range(n) if npred[j] == 0]
        heapq.heapify(heap)
        out = []
        while heap:
            _, j = heapq.heappop(heap)
            out.append(j)
            for s in succs[j]:
                npred[s] -= 1
                if npred[s] == 0:
                    heapq.heappush(heap, (prio[s], s))
        return out

    # sequential fallback
    seq = [0] * n
    tcur = 0
    for j in topo:
        t = max(tcur, rel[j])
        for p in preds[j]:
            t = max(t, seq[p] + dur[p])
        seq[j] = t
        tcur = t + dur[j]
    best_mk = max([seq[j] + dur[j] for j in range(n)] + [0])
    best_st = seq[:]

    rng = random.Random(12345)
    energy = [sum(dm[j]) * dur[j] for j in range(n)]
    rules = [
        [(-tail[j], est0[j]) for j in range(n)],
        [(est0[j] - (LB0 - tail[j]), j) for j in range(n)],
        [(est0[j], -tail[j]) for j in range(n)],
        [(-(tail[j] + len(succs[j])), j) for j in range(n)],
        [(-tail[j] - 0.1 * energy[j], j) for j in range(n)],
        [(rel[j], -tail[j]) for j in range(n)],
    ]
    pop = []
    seen = set()

    def add_ind(lst):
        nonlocal best_mk, best_st
        mk, st, nl = evaluate(lst)
        if mk < best_mk:
            best_mk, best_st = mk, st[:]
        key = tuple(nl)
        if key in seen:
            return mk, False
        seen.add(key)
        return mk, (mk, nl)

    P = 32
    for pr in rules:
        mk, ind = add_ind(list_from_prio(pr))
        if ind:
            pop.append(ind)
    tries = 0
    while len(pop) < P and tries < 4 * P and time.perf_counter() - T0 < 0.25 and best_mk > LB0:
        tries += 1
        a = rng.random()
        pr = [(-tail[j] * (1.0 + a * 2 * rng.random()) + (est0[j] - LB0 + tail[j]) * rng.random() * 0.5, j)
              for j in range(n)]
        mk, ind = add_ind(list_from_prio(pr))
        if ind:
            pop.append(ind)

    def tour():
        a = pop[rng.randrange(len(pop))]
        b = pop[rng.randrange(len(pop))]
        return a if a[0] <= b[0] else b

    stall = 0
    last_best = best_mk
    while pop and n > 1 and best_mk > LB0 and time.perf_counter() - T0 < GA_END:
        ma = tour()[1]
        fa = tour()[1]
        qp = rng.randrange(1, n)
        child = ma[:qp]
        ins = set(child)
        child += [x for x in fa if x not in ins]
        pm = 0.03 + 0.1 * rng.random()
        for i in range(n - 1):
            if rng.random() < pm:
                a, b = child[i], child[i + 1]
                if a not in predset[b]:
                    child[i], child[i + 1] = b, a
        mk, ind = add_ind(child)
        if ind:
            wi = 0
            for i in range(1, len(pop)):
                if pop[i][0] > pop[wi][0]:
                    wi = i
            if mk <= pop[wi][0]:
                pop[wi] = ind
        if best_mk < last_best:
            last_best = best_mk
            stall = 0
        else:
            stall += 1
        if stall > 400:
            stall = 0
            pop.sort(key=lambda x: x[0])
            keep = pop[:max(2, len(pop) // 4)]
            pop = keep
            for _k in range(P - len(keep)):
                if time.perf_counter() - T0 > GA_END:
                    break
                pr = [(-tail[j] * (1.0 + 1.5 * rng.random()), j) for j in range(n)]
                mk, ind = add_ind(list_from_prio(pr))
                if ind:
                    pop.append(ind)
            if not pop:
                break

    # ---------- Schedule-or-Postpone branch and bound with LDS ----------
    best = [best_mk, best_st[:]]
    st = [-1] * n
    usage = [[0] * L for _ in range(R)]
    nodes = [0]
    stop = [False]
    cut = [False]

    def place(j, t, sign):
        e = t + dur[j]
        for r, u in dem[j]:
            ur = usage[r]
            v = sign * u
            for tt in range(t, e):
                ur[tt] += v

    def dfs(post, curmk, nfix, disc):
        if stop[0]:
            return
        nodes[0] += 1
        if (nodes[0] & 63) == 0 and time.perf_counter() - T0 > BUDGET:
            stop[0] = True
            return
        if nfix == n:
            if curmk < best[0]:
                best[0] = curmk
                best[1] = st[:]
            return
        UB = best[0]
        if curmk >= UB:
            return
        ls = [0] * n
        elig = []
        lb = curmk
        for j in topo:
            if st[j] >= 0:
                continue
            t = rel[j]
            el = True
            for p in preds[j]:
                if st[p] >= 0:
                    v = st[p] + dur[p]
                else:
                    v = ls[p] + dur[p]
                    el = False
                if v > t:
                    t = v
            if el:
                t = earliest(usage, j, t)
                elig.append(j)
            ls[j] = t
            v = t + tail[j]
            if v > lb:
                lb = v
                if lb >= UB:
                    return
        T = UB - 1
        for r in range(R):
            E = 0
            t0 = None
            for j in range(n):
                if st[j] < 0 and dm[j][r] > 0:
                    E += dm[j][r] * dur[j]
                    if t0 is None or ls[j] < t0:
                        t0 = ls[j]
            if E == 0:
                continue
            if T <= t0:
                return
            avail = cap[r] * (T - t0)
            for f in range(n):
                if st[f] >= 0 and dm[f][r] > 0:
                    a = max(st[f], t0)
                    b = min(st[f] + dur[f], T)
                    if b > a:
                        avail -= dm[f][r] * (b - a)
            if E > avail:
                return
        for j in elig:
            if not dem[j]:
                t = ls[j]
                st[j] = t
                dfs(post, max(curmk, t + dur[j]), nfix + 1, disc)
                st[j] = -1
                return
        newpost = {}
        sel = []
        for j in elig:
            if j in post:
                if ls[j] > post[j]:
                    sel.append(j)
                else:
                    newpost[j] = post[j]
            else:
                sel.append(j)
        if not sel:
            return
        j = min(sel, key=lambda x: (ls[x], -tail[x], x))
        e = ls[j]
        for k in newpost:
            if newpost[k] < e:
                return
        st[j] = e
        place(j, e, 1)
        dfs(newpost, max(curmk, e + dur[j]), nfix + 1, disc)
        place(j, e, -1)
        st[j] = -1
        if stop[0]:
            return
        if disc > 0:
            np2 = dict(newpost)
            np2[j] = e
            dfs(np2, curmk, nfix, disc - 1)
        else:
            cut[0] = True

    k = 0
    while not stop[0] and best[0] > LB0 and k <= 2 * n + 2:
        if time.perf_counter() - T0 > BUDGET:
            break
        cut[0] = False
        try:
            dfs({}, 0, 0, k)
        except RecursionError:
            break
        if stop[0] or best[0] <= LB0:
            break
        if not cut[0]:
            break
        k += 1

    cand = [best[1], best_st, seq]
    for c in cand:
        sd = {ids[j]: int(c[j]) for j in range(n)}
        if _check(jobs, res, sd):
            state["output"] = {"status": "ok", "start": sd}
            return state
    state["output"] = {"status": "ok", "start": {ids[j]: int(seq[j]) for j in range(n)}}
    return state

import time
import random
import math


def _validate(inp):
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for k, i in enumerate(ids):
        idx[i] = k
    for j in jobs:
        jid = str(j.get("id"))
        for p in (j.get("after") or []):
            if str(p) not in idx:
                return "job %s references unknown job %s" % (jid, p), None
        for r, u in (j.get("requires") or {}).items():
            if r not in resources:
                return "job %s requires unknown resource %s" % (jid, r), None
            if u > resources[r]:
                return "job %s requires %s units of %s > capacity %s" % (jid, u, r, resources[r]), None
    n = len(jobs)
    preds = []
    for j in jobs:
        ps = []
        seen = set()
        for p in (j.get("after") or []):
            k = idx[str(p)]
            if k not in seen:
                seen.add(k)
                ps.append(k)
        preds.append(ps)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
            indeg[j] += 1
    topo = []
    stack = [j for j in range(n) if indeg[j] == 0]
    while stack:
        j = stack.pop()
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        cyc = [ids[j] for j in range(n) if indeg[j] > 0][:6]
        return "precedence cycle among " + ", ".join(cyc), None
    return None, (ids, preds, succs, topo)


def solve(state, params):
    T0 = time.perf_counter()
    HEUR_END = T0 + 0.33
    DEADLINE = T0 + 1.12
    inp = state.get("input") or {}
    reason, parsed = _validate(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    ids, preds, succs, topo = parsed
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    caps = [resources[r] for r in rnames]
    R = len(rnames)
    dur = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0)) for j in jobs]
    req = []
    for k, j in enumerate(jobs):
        rq = []
        if dur[k] > 0:
            for r, u in (j.get("requires") or {}).items():
                if u > 0:
                    rq.append((ridx[r], u))
        req.append(rq)
    rank = [0] * n
    for k, j in enumerate(topo):
        rank[j] = k

    def makespan(st):
        m = 0
        for j in range(n):
            f = st[j] + dur[j]
            if f > m:
                m = f
        return m

    def check(st):
        if st is None or len(st) != n:
            return False
        for j in range(n):
            if not isinstance(st[j], int) or st[j] < rel[j]:
                return False
            for p in preds[j]:
                if st[j] < st[p] + dur[p]:
                    return False
        use = {}
        for j in range(n):
            if dur[j] <= 0:
                continue
            for r, u in req[j]:
                for t in range(st[j], st[j] + dur[j]):
                    key = (r, t)
                    v = use.get(key, 0) + u
                    if v > caps[r]:
                        return False
                    use[key] = v
        return True

    # fallback: fully sequential schedule
    seq = [0] * n
    cur = 0
    for j in topo:
        t = max(cur, rel[j])
        seq[j] = t
        cur = t + dur[j]
    best = seq
    UB = makespan(seq)

    # heads / tails / lower bound
    head = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, head[p] + dur[p])
        head[j] = e
    tail = [0] * n
    for j in reversed(topo):
        t = 0
        for s in succs[j]:
            t = max(t, tail[s])
        tail[j] = t + dur[j]
    LB = 0
    for j in range(n):
        LB = max(LB, head[j] + tail[j])
    for r in range(R):
        items = []
        for j in range(n):
            for rr, u in req[j]:
                if rr == r:
                    items.append((head[j], dur[j] * u))
        items.sort(reverse=True)
        E = 0
        for h, e in items:
            E += e
            if caps[r] > 0:
                LB = max(LB, h + (E + caps[r] - 1) // caps[r])
    nsucc = [0] * n
    reach = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m |= reach[s] | (1 << s)
        reach[j] = m
        nsucc[j] = bin(m).count("1")

    H = max(rel) + sum(dur) + 2 if n else 2

    def earliest(prof, t, d, rq):
        while True:
            ok = True
            for tau in range(t, t + d):
                for r, u in rq:
                    if prof[r][tau] + u > caps[r]:
                        t = tau + 1
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return t

    def sgs(order):
        prof = [[0] * H for _ in range(R)]
        st = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = st[p] + dur[p]
                if f > t:
                    t = f
            d = dur[j]
            rq = req[j]
            if d > 0 and rq:
                t = earliest(prof, t, d, rq)
                for tau in range(t, t + d):
                    for r, u in rq:
                        prof[r][tau] += u
            st[j] = t
        return st

    def latest(prof, t, d, rq, lo):
        while t >= lo:
            ok = True
            for tau in range(t + d - 1, t - 1, -1):
                for r, u in rq:
                    if prof[r][tau] + u > caps[r]:
                        t = tau - d
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return t
        return None

    def backward(st):
        ms = makespan(st)
        order = sorted(range(n), key=lambda j: (-(st[j] + dur[j]), -rank[j]))
        prof = [[0] * (ms + 1) for _ in range(R)]
        new = [0] * n
        for j in order:
            d = dur[j]
            ub = ms - d
            for s in succs[j]:
                ub = min(ub, new[s] - d)
            if ub < rel[j]:
                return None
            rq = req[j]
            if d > 0 and rq:
                t = latest(prof, ub, d, rq, rel[j])
                if t is None:
                    return None
                for tau in range(t, t + d):
                    for r, u in rq:
                        prof[r][tau] += u
            else:
                t = ub
            new[j] = t
        return new

    def forward(st):
        order = sorted(range(n), key=lambda j: (st[j], rank[j]))
        return sgs(order)

    def fbi(st):
        curst = st
        curm = makespan(st)
        for _ in range(6):
            b = backward(curst)
            if b is None:
                break
            f = forward(b)
            fm = makespan(f)
            if fm < curm:
                curst, curm = f, fm
            else:
                break
        return curst

    rng = random.Random(12345)
    cp = LB
    rules = [
        [cp - tail[j] for j in range(n)],
        [head[j] for j in range(n)],
        [-tail[j] for j in range(n)],
        [-nsucc[j] for j in range(n)],
        [-(tail[j] + sum(u for _, u in req[j]) * dur[j] * 0.3) for j in range(n)],
        [rel[j] - tail[j] * 0.5 for j in range(n)],
    ]

    def make_list(prio, noise):
        indeg = [len(preds[j]) for j in range(n)]
        elig = [j for j in range(n) if indeg[j] == 0]
        keys = {}
        for j in elig:
            keys[j] = prio[j] + rng.random() * noise
        order = []
        while elig:
            bi = 0
            bk = keys[elig[0]]
            for i in range(1, len(elig)):
                k = keys[elig[i]]
                if k < bk:
                    bk = k
                    bi = i
            j = elig.pop(bi)
            order.append(j)
            for s in succs[j]:
                indeg[s] -= 1
                if indeg[s] == 0:
                    elig.append(s)
                    keys[s] = prio[s] + rng.random() * noise
        return order

    def consider(st):
        nonlocal best, UB
        m = makespan(st)
        if m < UB and check(st):
            best = list(st)
            UB = m

    it = 0
    while UB > LB:
        if it >= len(rules) and time.perf_counter() > HEUR_END:
            break
        if it < len(rules):
            pr = rules[it]
            noise = 0.0
        else:
            pr = rules[rng.randrange(len(rules))]
            noise = rng.choice([1.0, 3.0, 6.0, 12.0])
        it += 1
        st = sgs(make_list(pr, noise))
        consider(st)
        st2 = fbi(st)
        consider(st2)

    # ---------- deadline-driven constraint propagation search ----------
    cand_all = [j for j in range(n) if dur[j] > 0 and req[j]]

    def run_decision(T):
        fixed = [-1] * n
        fixprof = [[0] * max(T, 1) for _ in range(R)]
        marks = {}
        timed_out = [False]
        counter = [0]

        def propagate():
            est = [0] * n
            lst = [0] * n
            for j in topo:
                e = rel[j]
                for p in preds[j]:
                    v = est[p] + dur[p]
                    if v > e:
                        e = v
                if fixed[j] >= 0:
                    if e > fixed[j]:
                        return None
                    e = fixed[j]
                est[j] = e
            for j in reversed(topo):
                l = T - dur[j]
                for s in succs[j]:
                    v = lst[s] - dur[j]
                    if v < l:
                        l = v
                if fixed[j] >= 0:
                    if l < fixed[j]:
                        return None
                    l = fixed[j]
                if l < est[j]:
                    return None
                lst[j] = l
            cand = [j for j in cand_all if fixed[j] < 0]
            for _ in range(60):
                usage = [row[:] for row in fixprof]
                own = {}
                for j in cand:
                    a = lst[j]
                    b = est[j] + dur[j]
                    if a < b:
                        own[j] = (a, b)
                        for r, u in req[j]:
                            row = usage[r]
                            for tau in range(a, b):
                                row[tau] += u
                changed = False
                for j in cand:
                    d = dur[j]
                    rq = req[j]
                    a, b = own.get(j, (0, 0))
                    t = est[j]
                    L = lst[j]
                    while t <= L:
                        ok = True
                        for tau in range(t, t + d):
                            inown = a <= tau < b
                            for r, u in rq:
                                v = usage[r][tau]
                                if inown:
                                    v -= u
                                if v + u > caps[r]:
                                    ok = False
                                    break
                            if not ok:
                                t = tau + 1
                                break
                        if ok:
                            break
                    if t > L:
                        return None
                    if t != est[j]:
                        est[j] = t
                        changed = True
                    t = L
                    lo = est[j]
                    while t >= lo:
                        ok = True
                        for tau in range(t + d - 1, t - 1, -1):
                            inown = a <= tau < b
                            for r, u in rq:
                                v = usage[r][tau]
                                if inown:
                                    v -= u
                                if v + u > caps[r]:
                                    ok = False
                                    break
                            if not ok:
                                t = tau - d
                                break
                        if ok:
                            break
                    if t < lo:
                        return None
