def bnb_node(state, params):
    if state.get("is_infeasible"):
        return state
    best = state.get("_best_starts")
    if not best:
        return state
    T0 = time.perf_counter()
    budget = 1.17 - float(state.get("_t_used", 0.0))
    if budget > 0.8:
        budget = 0.8
    if budget < 0.03:
        return state
    deadline = T0 + budget
    try:
        P = _prep(state["input"])
    except Exception:
        return state
    n = P["n"]
    cap = P["cap"]
    R = P["R"]
    dur = P["dur"]
    rel = P["rel"]
    preds = P["preds"]
    succs = P["succs"]
    req = P["req"]
    topo = P["topo"]
    tail = P["tail"]
    lb = P["lb"]
    UB0 = max(best[j] + dur[j] for j in range(n))
