    visited = set()
    guide = [float(x) for x in best]
    mode = {"tfirst": True}

    def fit(j, t, limit):
        rq = req[j]
        d = dur[j]
        if t > limit:
            return -1
        if not rq:
            return t
        while True:
            if t > limit:
                return -1
            bad = -1
            for (r, u) in rq:
                row = usage[r]
                lim = cap[r] - u
                tt = t + d - 1
                while tt >= t and tt > bad:
                    if row[tt] > lim:
                        bad = tt
                        break
                    tt -= 1
            if bad < 0:
                return t
            t = bad + 1

