        inc["nodes"] += 1
        if (inc["nodes"] & 127) == 0 and time.perf_counter() > deadline:
            inc["stop"] = True
        if inc["stop"]:
            return
        if inc["limit"] and inc["nodes"] > inc["limit"]:
            inc["cut"] = True
            return
        UBc = inc["UB"]
        if cnt == n:
            if cur_mk < UBc:
                inc["UB"] = cur_mk
                inc["sol"] = list(start)
