            if dur[j] == 0 and tail[j] == 0:
                lim = UBc - 1
            t = fit(j, h[j], lim)
            if t < 0:
                return
            if mode["tfirst"]:
                children.append((t, guide[j], j))
            else:
                children.append((guide[j] + 0.3 * t, t, j))
        children.sort()
        for c in children:
            j = c[2]
            if mode["tfirst"]:
                t = c[0]
            else:
                t = c[1]
            UBn = inc["UB"]
            tl = tail[j] if tail[j] > 0 else 0
            if t + tl > UBn - 1 and not (dur[j] == 0 and tail[j] == 0 and t <= UBn - 1):
                continue
            d = dur[j]
            start[j] = t
            placed[j] = True
            for (r, u) in req[j]:
                row = usage[r]
                for tt in range(t, t + d):
                    row[tt] += u
                rem[r] -= u * d
            for s in succs[j]:
                npl[s] -= 1
            nm = mask | (1 << j)
            key = (nm, t, tuple((i, start[i] + dur[i]) for i in range(n)
                                if placed[i] and start[i] + dur[i] > t))
            if key not in visited:
                if len(visited) > 250000:
                    visited.clear()
                visited.add(key)
                f = t + d
                dfs(t, cur_mk if cur_mk > f else f, cnt + 1, nm)
            for s in succs[j]:
                npl[s] += 1
            for (r, u) in req[j]:
                row = usage[r]
                for tt in range(t, t + d):
                    row[tt] -= u
                rem[r] += u * d
